build-standalone-mobile.sh.content:
#!/bin/bash
echo "🔧 Creating standalone mobile build for APK..."

# Create minimal mobile-only build
mkdir -p mobile-build/www

# Create minimal index.html for mobile
cat > mobile-build/www/index.html << 'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>GabAi</title>
    <style>
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { 
            font-family: -apple-system, BlinkMacSystemFont, sans-serif;
            background: #3b82f6;
            color: white;
            height: 100vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            text-align: center;
            padding: 20px;
        }
        .logo { font-size: 3rem; font-weight: bold; margin-bottom: 2rem; }
        .status { font-size: 1.2rem; margin-bottom: 1rem; }
        .btn { 
            background: white; 
            color: #3b82f6; 
            border: none; 
            padding: 1rem 2rem; 
            border-radius: 0.5rem; 
            font-size: 1.1rem; 
            cursor: pointer;
            margin: 0.5rem;
        }
        .btn:hover { background: #f8fafc; }
        .features { margin-top: 2rem; text-align: left; }
        .feature { margin: 0.5rem 0; }
    </style>
</head>
<body>
    <div class="logo">GabAi</div>
    <div class="status" id="status">Loading mobile app...</div>

    <button class="btn" onclick="signIn()">Sign In with Google</button>
    <button class="btn" onclick="testFeatures()">Test Features</button>

    <div class="features">
        <h3>Features:</h3>
        <div class="feature">✓ Voice AI Assistant</div>
        <div class="feature">✓ Smart Lists</div>
        <div class="feature">✓ Calendar & Reminders</div>
        <div class="feature">✓ OCR Text Extraction</div>
    </div>

    <script>
        console.log('📱 Standalone mobile app loaded');
        document.getElementById('status').textContent = 'Mobile app ready!';

        function signIn() {
            // In real APK, this would use Capacitor OAuth
            window.location.href = 'https://gabai.ai/api/login';
        }

        function testFeatures() {
            alert('Testing mobile features...\n\n' +
                  'This is a standalone mobile version of GabAi.\n' +
                  'All core features are functional:\n\n' +
                  '• Voice AI conversations\n' +
                  '• Smart shopping & task lists\n' +
                  '• Calendar integration\n' +
                  '• Image text extraction\n' +
                  '• Real-time notifications');
        }

        // Test Capacitor readiness
        document.addEventListener('deviceready', function() {
            console.log('📱 Capacitor device ready');
            document.getElementById('status').textContent = 'Native mobile features ready!';
        });
    </script>
</body>
</html>
EOF

# Copy Android config
cp -r android mobile-build/
cp capacitor.config.ts mobile-build/
cp package.json mobile-build/

# Create simple package.json for mobile
cat > mobile-build/package.json << 'EOF'
{
  "name": "gabai-mobile",
  "version": "1.0.0",
  "description": "GabAi Mobile App",
  "main": "index.js",
  "dependencies": {
    "@capacitor/android": "^6.1.2",
    "@capacitor/core": "^6.1.2"
  }
}
EOF

# Create VoltBuilder config
cat > mobile-build/voltbuilder.json << 'EOF'
{
  "platform": "android",
  "buildType": "release",
  "keystore": {
    "file": "gabai-release.keystore",
    "password": "GabAi2024!Mobile",
    "alias": "gabai",
    "aliasPassword": "GabAi2024!Mobile"
  }
}
EOF

echo "✅ Standalone mobile build created in mobile-build/"

# Create ZIP for VoltBuilder
cd mobile-build
zip -r ../gabai-standalone-mobile.zip . -x "*.git*" "node_modules/*" "*.DS_Store"
cd ..

echo "📦 Created gabai-standalone-mobile.zip"
echo "🚀 Upload this minimal version to test APK loading"

build-voltbuilder-android-only.sh.content:
#!/bin/bash

# VoltBuilder Android-Only Package
# Removes all iOS dependencies to prevent version conflicts

echo "🔧 Creating Android-only VoltBuilder package..."

# Clean previous builds
rm -rf gabai-voltbuilder-ANDROID-ONLY.zip
rm -rf voltbuilder-android

# Create temporary directory
mkdir -p voltbuilder-android

echo "📁 Setting up Android-only structure..."

# Create package.json with ONLY Android dependencies
cat > voltbuilder-android/package.json << 'EOF'
{
  "name": "gabai-mobile-app",
  "version": "1.0.0",
  "description": "GabAi Voice Assistant Mobile App",
  "private": true,
  "dependencies": {
    "@capacitor/android": "5.7.8",
    "@capacitor/cli": "5.7.8",
    "@capacitor/core": "5.7.8"
  }
}
EOF

# Create voltbuilder.json that excludes iOS platform
cat > voltbuilder-android/voltbuilder.json << 'EOF'
{
  "platform": "android",
  "java": "17",
  "verbose": true,
  "capacitor": {
    "version": "5.7.8",
    "platforms": ["android"]
  },
  "gradle": {
    "compileSdkVersion": "33",
    "targetSdkVersion": "33",
    "buildToolsVersion": "33.0.2",
    "sourceCompatibility": "17",
    "targetCompatibility": "17"
  },
  "excludePlatforms": ["ios"]
}
EOF

# Create Capacitor config for Android only
cat > voltbuilder-android/capacitor.config.ts << 'EOF'
const config = {
  appId: 'ai.gabai.app',
  appName: 'GabAi',
  webDir: 'www',
  bundledWebRuntime: false,
  server: {
    url: 'https://gabai.ai',
    cleartext: false
  },
  plugins: {
    SplashScreen: {
      launchShowDuration: 2500,
      launchAutoHide: true,
      backgroundColor: "#3b82f6",
      androidScaleType: "CENTER_CROP",
      showSpinner: false,
      androidSpinnerStyle: "large",
      spinnerColor: "#ffffff",
      splashFullScreen: true,
      splashImmersive: true
    },
    StatusBar: {
      style: 'dark',
      overlaysWebView: true,
      backgroundColor: '#00000000'
    }
  },
  android: {
    buildOptions: {
      keystorePath: '',
      keystorePassword: '',
      keystoreAlias: '',
      keystoreAliasPassword: '',
      releaseType: 'APK'
    }
  }
};

export default config;
EOF

# Create .npmrc to force legacy peer deps resolution
cat > voltbuilder-android/.npmrc << 'EOF'
legacy-peer-deps=true
force=true
EOF

# Create gradle.properties with consistent settings
cat > voltbuilder-android/gradle.properties << 'EOF'
# Java Version
org.gradle.jvmargs=-Xmx2048m -XX:MaxMetaspaceSize=512m
android.useAndroidX=true
android.enableJetifier=true

# Android SDK versions
android.compileSdkVersion=33
android.targetSdkVersion=33
android.buildToolsVersion=33.0.2

# Java compatibility
android.compileOptions.sourceCompatibility=17
android.compileOptions.targetCompatibility=17
EOF

# Create www directory with all static files
echo "📦 Copying static files to www directory..."
mkdir -p voltbuilder-android/www

# Copy the built static files directly
cp dist/public/index.html voltbuilder-android/www/
cp -r dist/public/assets voltbuilder-android/www/

# Mobile auth callback
cat > voltbuilder-android/www/mobile-auth-callback.html << 'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>GabAi - Authentication Complete</title>
    <style>
        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif;
            display: flex;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            background: linear-gradient(135deg, #3b82f6, #1d4ed8);
            color: white;
            text-align: center;
        }
        .container {
            max-width: 400px;
            padding: 2rem;
        }
        .success-icon {
            font-size: 4rem;
            margin-bottom: 1rem;
        }
        .message {
            font-size: 1.2rem;
            margin-bottom: 1rem;
        }
        .loading {
            font-size: 0.9rem;
            opacity: 0.8;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="success-icon">✅</div>
        <div class="message">Authentication successful!</div>
        <div class="loading">Redirecting you back to GabAi...</div>
    </div>

    <script>
        console.log('📱 Mobile auth callback page loaded');

        const urlParams = new URLSearchParams(window.location.search);
        const token = urlParams.get('token');
        const success = urlParams.get('success');

        if (token && success === 'true') {
            console.log('📱 Storing authentication token for mobile app');
            localStorage.setItem('gabai_mobile_token', token);
            localStorage.setItem('gabai_mobile_auth_success', 'true');
            localStorage.setItem('gabai_token', token);

            setTimeout(() => {
                try {
                    window.close();
                } catch (e) {
                    console.log('Could not close window');
                }

                try {
                    window.location.href = 'ai.gabai.app://oauth/success';
                } catch (e) {
                    console.log('Could not use deep link');
                }

                setTimeout(() => {
                    window.location.href = '/';
                }, 2000);
            }, 1000);
        } else {
            console.error('❌ Authentication failed');
            document.querySelector('.success-icon').textContent = '❌';
            document.querySelector('.message').textContent = 'Authentication failed';
            document.querySelector('.loading').textContent = 'Please try again';

            setTimeout(() => {
                window.location.href = '/';
            }, 3000);
        }
    </script>
</body>
</html>
EOF

echo "📋 Creating build instructions..."
cat > voltbuilder-android/BUILD-INSTRUCTIONS.md << 'EOF'
# GabAi Mobile App - ANDROID ONLY

## VoltBuilder Upload Instructions

1. **Upload this ZIP to VoltBuilder.com**
2. **Platform: Android**
3. **Package: gabai-voltbuilder-ANDROID-ONLY.zip**

## Dependency Conflict Fix

The previous error was caused by:
- VoltBuilder auto-installing @capacitor/ios@7.4.2
- Which required @capacitor/core@^7.4.0
- But we specified @capacitor/core@5.7.8
- Creating an unresolvable dependency conflict

## Solution

- Explicitly excluded iOS platform
- Added .npmrc with legacy-peer-deps=true
- Only Android dependencies in package.json
- Consistent Capacitor 5.7.8 versions throughout

## What This Package Contains

- ✅ Android-only Capacitor 5.7.8
- ✅ No iOS dependencies to cause conflicts
- ✅ Legacy peer dependency resolution
- ✅ Java 17 compatibility throughout
- ✅ Static pre-built files in www/ directory
- ✅ Mobile authentication callback

Built: $(date)
EOF

echo "📱 Creating final package..."
cd voltbuilder-android
zip -r ../gabai-voltbuilder-ANDROID-ONLY.zip . -x "*.DS_Store" "*.git*"
cd ..

# Clean up
rm -rf voltbuilder-android

echo "✅ Package created: gabai-voltbuilder-ANDROID-ONLY.zip"
echo "📱 This package removes iOS dependencies that caused version conflicts"
echo ""
echo "🔧 ANDROID-ONLY FIXES:"
echo "   - Removed all iOS platform dependencies"
echo "   - Added .npmrc for legacy peer dependency resolution"
echo "   - Consistent Capacitor 5.7.8 versions"
echo "   - Explicit Android-only platform specification"
echo ""
echo "🚀 Upload gabai-voltbuilder-ANDROID-ONLY.zip to VoltBuilder.com"

