build-voltbuilder-fixed.sh.content:
#!/bin/bash

# Complete VoltBuilder Build Script with Mobile Authentication
# This script creates a production-ready package for APK building

echo "🚀 Building complete GabAi VoltBuilder package with mobile auth..."

# Clean previous builds
rm -rf gabai-voltbuilder-AUTH-FIXED.zip
rm -rf voltbuilder-temp

# Create temporary directory
mkdir -p voltbuilder-temp

echo "📱 Creating mobile auth callback page..."
# Ensure mobile auth callback exists in dist
mkdir -p dist/public
cp dist/public/mobile-auth-callback.html voltbuilder-temp/ 2>/dev/null || echo "Creating mobile auth callback page..."

cat > voltbuilder-temp/mobile-auth-callback.html << 'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>GabAi - Authentication Complete</title>
    <style>
        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif;
            display: flex;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            background: linear-gradient(135deg, #3b82f6, #1d4ed8);
            color: white;
            text-align: center;
        }
        .container {
            max-width: 400px;
            padding: 2rem;
        }
        .success-icon {
            font-size: 4rem;
            margin-bottom: 1rem;
        }
        .message {
            font-size: 1.2rem;
            margin-bottom: 1rem;
        }
        .loading {
            font-size: 0.9rem;
            opacity: 0.8;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="success-icon">✅</div>
        <div class="message">Authentication successful!</div>
        <div class="loading">Redirecting you back to GabAi...</div>
    </div>

    <script>
        // Mobile OAuth callback handler for VoltBuilder/Capacitor apps
        console.log('📱 Mobile auth callback page loaded');

        // Get the token from URL params
        const urlParams = new URLSearchParams(window.location.search);
        const token = urlParams.get('token');
        const success = urlParams.get('success');

        console.log('🔑 Token received:', !!token);
        console.log('✅ Success status:', success);

        if (token && success === 'true') {
            console.log('📱 Storing authentication token for mobile app');

            // Store the token in localStorage for the main app to pick up
            localStorage.setItem('gabai_mobile_token', token);
            localStorage.setItem('gabai_mobile_auth_success', 'true');

            console.log('💾 Token stored in localStorage');

            // For Capacitor apps, try to redirect back to the main app
            if (window.location.protocol === 'https:' && window.location.hostname === 'gabai.ai') {
                // In browser context, redirect to main app
                console.log('🌐 Browser context - redirecting to main app');
                setTimeout(() => {
                    window.location.href = '/';
                }, 2000);
            } else {
                // In native app context, close this window/webview
                console.log('📱 Native context - attempting to close webview');

                // Try multiple methods to close or navigate back
                try {
                    // Method 1: Close window if possible
                    window.close();
                } catch (e) {
                    console.log('Could not close window');
                }

                try {
                    // Method 2: Navigate back to app
                    window.location.href = 'ai.gabai.app://oauth/success';
                } catch (e) {
                    console.log('Could not use deep link');
                }

                try {
                    // Method 3: Navigate to main page as fallback
                    setTimeout(() => {
                        window.location.href = '/';
                    }, 3000);
                } catch (e) {
                    console.log('Could not redirect');
                }
            }
        } else {
            console.error('❌ Authentication failed or missing token');
            document.querySelector('.success-icon').textContent = '❌';
            document.querySelector('.message').textContent = 'Authentication failed';
            document.querySelector('.loading').textContent = 'Please try again';

            setTimeout(() => {
                window.location.href = '/';
            }, 3000);
        }
    </script>
</body>
</html>
EOF

echo "🔧 Building production frontend..."
# Build the frontend with all mobile auth fixes
npm run build

echo "📦 Creating package structure..."
# Copy essential files
cp package.json voltbuilder-temp/
cp capacitor.config.ts voltbuilder-temp/
cp -r dist voltbuilder-temp/

# Create the server-only package.json with fixed dependencies
cat > voltbuilder-temp/package-server-only.json << 'EOF'
{
  "name": "gabai-mobile-app",
  "version": "1.0.0",
  "description": "GabAi Voice Assistant Mobile App",
  "main": "dist/server.js",
  "scripts": {
    "start": "node dist/server.js",
    "build": "esbuild server/index.ts --platform=node --packages=external --bundle --format=esm --outdir=dist"
  },
  "dependencies": {
    "@neondatabase/serverless": "^0.10.1",
    "bcrypt": "^5.1.0",
    "connect-pg-simple": "^9.0.1",
    "drizzle-orm": "^0.36.4",
    "express": "^4.18.2",
    "express-session": "^1.17.3",
    "memorystore": "^1.6.7",
    "multer": "^1.4.5-lts.1",
    "nanoid": "^5.0.2",
    "openai": "^4.28.4",
    "passport": "^0.7.0",
    "passport-google-oauth20": "^2.0.0",
    "ws": "^8.14.2",
    "zod": "^3.22.4"
  },
  "devDependencies": {
    "@types/bcrypt": "^5.0.0",
    "@types/express": "^4.17.21",
    "@types/express-session": "^1.17.10",
    "@types/multer": "^1.4.11",
    "@types/node": "^20.10.4",
    "@types/passport": "^1.0.16",
    "@types/passport-google-oauth20": "^2.0.14",
    "@types/ws": "^8.5.10",
    "esbuild": "^0.19.8",
    "typescript": "^5.3.3"
  }
}
EOF

echo "🔗 Copying server files..."
