  "name": "gabai-mobile-app",
  "version": "1.0.0",
  "description": "GabAi Voice Assistant Mobile App",
  "private": true
}
EOF

# Create voltbuilder.json with explicit Java 17 settings
cat > voltbuilder-java-fix/voltbuilder.json << 'EOF'
{
  "platform": "android",
  "java": "17",
  "verbose": true,
  "gradle": {
    "compileSdkVersion": "34",
    "targetSdkVersion": "34",
    "buildToolsVersion": "34.0.0",
    "sourceCompatibility": "17",
    "targetCompatibility": "17"
  },
  "options": {
    "javaVersion": "17",
    "sourceCompatibility": "17",
    "targetCompatibility": "17"
  }
}
EOF

# Copy Capacitor config with Android-specific Java settings
cat > voltbuilder-java-fix/capacitor.config.ts << 'EOF'
const config = {
  appId: 'ai.gabai.app',
  appName: 'GabAi',
  webDir: 'www',
  bundledWebRuntime: false,
  server: {
    url: 'https://gabai.ai',
    cleartext: false
  },
  plugins: {
    SplashScreen: {
      launchShowDuration: 2500,
      launchAutoHide: true,
      backgroundColor: "#3b82f6",
      androidScaleType: "CENTER_CROP",
      showSpinner: false,
      androidSpinnerStyle: "large",
      spinnerColor: "#ffffff",
      splashFullScreen: true,
      splashImmersive: true
    },
    StatusBar: {
      style: 'dark',
      overlaysWebView: true,
      backgroundColor: '#00000000'
    },
    Keyboard: {}
  },
  android: {
    buildOptions: {
      keystorePath: '',
      keystorePassword: '',
      keystoreAlias: '',
      keystoreAliasPassword: '',
      releaseType: 'APK'
    }
  }
};

export default config;
EOF

# Create gradle.properties to force Java 17
cat > voltbuilder-java-fix/gradle.properties << 'EOF'
# Java Version
org.gradle.jvmargs=-Xmx2048m -XX:MaxMetaspaceSize=512m
android.useAndroidX=true
android.enableJetifier=true

# Force Java 17
org.gradle.java.home=/usr/lib/jvm/java-17-openjdk-amd64
java.home=/usr/lib/jvm/java-17-openjdk-amd64

# Compatibility
android.compileSdkVersion=34
android.targetSdkVersion=34
android.buildToolsVersion=34.0.0
EOF

# Create www directory with all static files
echo "📦 Copying static files to www directory..."
mkdir -p voltbuilder-java-fix/www

# Copy the built static files directly
cp dist/public/index.html voltbuilder-java-fix/www/
cp -r dist/public/assets voltbuilder-java-fix/www/

# Ensure mobile auth callback exists
cat > voltbuilder-java-fix/www/mobile-auth-callback.html << 'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>GabAi - Authentication Complete</title>
    <style>
        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif;
            display: flex;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            background: linear-gradient(135deg, #3b82f6, #1d4ed8);
            color: white;
            text-align: center;
        }
        .container {
            max-width: 400px;
            padding: 2rem;
        }
        .success-icon {
            font-size: 4rem;
            margin-bottom: 1rem;
        }
        .message {
            font-size: 1.2rem;
            margin-bottom: 1rem;
        }
        .loading {
            font-size: 0.9rem;
            opacity: 0.8;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="success-icon">✅</div>
        <div class="message">Authentication successful!</div>
        <div class="loading">Redirecting you back to GabAi...</div>
    </div>

    <script>
        console.log('📱 Mobile auth callback page loaded');

        const urlParams = new URLSearchParams(window.location.search);
        const token = urlParams.get('token');
        const success = urlParams.get('success');

        if (token && success === 'true') {
            console.log('📱 Storing authentication token for mobile app');
            localStorage.setItem('gabai_mobile_token', token);
            localStorage.setItem('gabai_mobile_auth_success', 'true');
            localStorage.setItem('gabai_token', token);

            setTimeout(() => {
                try {
                    window.close();
                } catch (e) {
                    console.log('Could not close window');
                }

                try {
                    window.location.href = 'ai.gabai.app://oauth/success';
                } catch (e) {
                    console.log('Could not use deep link');
                }

                setTimeout(() => {
                    window.location.href = '/';
                }, 2000);
            }, 1000);
        } else {
            console.error('❌ Authentication failed');
            document.querySelector('.success-icon').textContent = '❌';
            document.querySelector('.message').textContent = 'Authentication failed';
            document.querySelector('.loading').textContent = 'Please try again';

            setTimeout(() => {
                window.location.href = '/';
            }, 3000);
        }
    </script>
</body>
</html>
EOF

