@tailwind base;
@tailwind components;
@tailwind utilities;

/* CRITICAL MOBILE FIXES - Applied at CSS level */
html, body {
  overflow-x: hidden !important;
  max-width: 100vw !important;
}

/* CRITICAL: Fix input field text direction only */
input, textarea, [contenteditable] {
  direction: ltr !important;
  unicode-bidi: normal !important;
  text-align: left !important;
}

/* Allow natural text direction for content - use plaintext for proper RTL/LTR detection */
.chat-message-text, .user-content, .list-item-text, .shared-list-item {
  unicode-bidi: plaintext !important;
  text-align: start !important;
}

/* Force fullscreen viewport on mobile */
@viewport {
  width: device-width;
  initial-scale: 1.0;
  maximum-scale: 1.0;
  user-scalable: no;
  viewport-fit: cover;
}

/* Force larger mobile input fields for better usability */
.smart-list-input {
  font-size: 16px !important;
  min-height: 44px !important;
  height: 44px !important;
  padding: 12px 16px !important;
  line-height: 1.4 !important;
  direction: ltr !important;
  text-align: left !important;
}

/* Prevent iOS zoom on input focus and improve mobile usability */
input[type="text"], input[type="email"], input[type="password"], input[type="number"], input[type="search"], textarea, select {
  font-size: 16px !important;
  min-height: 44px !important;
  padding: 12px 16px !important;
  direction: ltr !important;
  text-align: left !important;
  unicode-bidi: normal !important;
  box-sizing: border-box !important;
}

/* Ensure proper text flow in chat messages - direction handled per-message */
.chat-message-text {
  unicode-bidi: plaintext !important;
  white-space: pre-wrap;
  word-wrap: break-word;
  overflow-wrap: break-word;
}

/* Override shadcn input styles for mobile */
.smart-list-input,
input.smart-list-input {
  font-size: 16px !important;
  min-height: 44px !important;
  height: 44px !important;
  padding: 12px 16px !important;
  line-height: 1.4 !important;
}

/* Full-screen PWA styles */
html, body {
  width: 100vw;
  max-width: 100vw;
  overflow-x: hidden;
  position: relative;
  height: 100vh;
  height: 100dvh; /* Dynamic viewport height for mobile */
}

/* Prevent horizontal scrolling */
*, *::before, *::after {
  max-width: 100%;
  box-sizing: border-box;
}

/* Mobile safe area and keyboard handling */
@supports (padding: max(0px)) {
  .safe-area-inset-top {
    padding-top: max(0.75rem, env(safe-area-inset-top));
  }

  .safe-area-inset-bottom {
    padding-bottom: max(0.75rem, env(safe-area-inset-bottom));
  }

  .safe-area-inset-left {
    padding-left: max(1rem, env(safe-area-inset-left));
  }

  .safe-area-inset-right {
    padding-right: max(1rem, env(safe-area-inset-right));
  }
}

/* Mobile keyboard accommodation */
@supports (height: 100dvh) {
  .mobile-safe-height {
    height: 100dvh;
  }
}

/* Improve touch handling for drag and drop */
.dnd-touch-handle {
  touch-action: none;
  -webkit-touch-callout: none;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
}

/* Prevent text selection during drag */
.dnd-container.dragging {
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
}

/* Main app container should fill viewport */
#root {
  width: 100vw;
  max-width: 100vw;
  overflow-x: hidden;
  min-height: 100vh;
  min-height: 100dvh;
}

/* PWA safe area support for notched devices */
body {
  padding-top: env(safe-area-inset-top);
  padding-bottom: env(safe-area-inset-bottom);
  padding-left: env(safe-area-inset-left);
  padding-right: env(safe-area-inset-right);
}

/* Mobile Scrolling Improvements for APK */
.mobile-scroll-container {
  -webkit-overflow-scrolling: touch;
  overflow-scrolling: touch;
  height: 100vh;
  max-height: 100vh;
  overscroll-behavior: contain;
}

/* APK Specific Styles */
@media (max-width: 768px) {
  .mobile-page {
    height: 100vh;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    padding-bottom: 120px;
  }

  .mobile-content {
    min-height: calc(100vh - 120px);
  }

  /* Smart Lists Mobile Improvements */
  .smart-list-input-container {
    background: white;
    border-radius: 12px;
    padding: 16px;
    margin: 8px 0;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  }

  .smart-list-item-row {
    padding: 12px 16px;
    border-radius: 8px;
    margin: 4px 0;
    min-height: 56px;
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .smart-list-category-header {
    padding: 8px 16px;
    margin: 16px 0 8px 0;
    font-weight: 600;
    font-size: 14px;
    opacity: 0.8;
  }

  .smart-list-button {
    min-height: 44px;
    min-width: 44px;
    padding: 12px;
  }

  .smart-list-voice-button {
    width: 48px;
    height: 48px;
    border-radius: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  /* Dark mode improvements for APK */
  .dark .smart-list-input-container {
    background: rgb(17, 24, 39);
    border: 1px solid rgb(55, 65, 81);
  }

  .dark .smart-list-item-row {
    border: 1px solid rgb(55, 65, 81);
  }

  /* Touch target improvements */
  @media (max-width: 768px) {
    .smart-list-input-container input {
      font-size: 16px !important;
      min-height: 48px !important;
    }

    .smart-list-input-container select {
      font-size: 16px !important;
      min-height: 48px !important;
    }
  }

  /* Hide scrollbar for tabs carousel */
  .scrollbar-hide {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }

  .scrollbar-hide::-webkit-scrollbar {
    display: none;
  }
}

/* Hide address bar on mobile when in standalone mode */
@media (display-mode: standalone) {
  body {
    -webkit-appearance: none;
  }
}

/* PWA mode specific styles */
.pwa-mode {
  padding-top: env(safe-area-inset-top, 20px);
}

/* Force prevent horizontal scroll on all elements */
body, html, #root, .App {
  overflow-x: hidden !important;
  max-width: 100vw !important;
  width: 100vw !important;
  position: relative !important;
}

/* Mobile Chat Layout - Keyboard Accommodation */
.mobile-input-container {
  position: fixed !important;
  bottom: 60px !important; /* Above bottom navigation */
  left: 0 !important;
  right: 0 !important;
  z-index: 50 !important;
  background: white !important;
  border-top: 1px solid #e5e7eb !important;
  padding: 12px 16px !important;
  /* Enhanced keyboard accommodation - CRITICAL for mobile */
  bottom: max(60px, calc(env(keyboard-inset-height, 0px) + 60px)) !important;
  /* Hardware acceleration for smooth positioning */
  transform: translate3d(0, 0, 0) !important;
  -webkit-transform: translate3d(0, 0, 0) !important;
  /* Prevent any viewport shifts */
  backface-visibility: hidden !important;
  -webkit-backface-visibility: hidden !important;
  /* Ensure it stays visible during keyboard transition */
  transition: transform 0.3s ease-out !important;
}

.mobile-input-wrapper {
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: 100%;
}

.mobile-text-input {
  flex: 1;
  font-size: 16px !important; /* Prevents zoom on iOS */
  min-height: 44px !important;
  border-radius: 22px !important;
  padding: 12px 16px !important;
  background: #f3f4f6 !important;
  border: 1px solid #d1d5db !important;
  /* Enhanced mobile support */
  -webkit-appearance: none !important;
  appearance: none !important;
  outline: none !important;
  touch-action: manipulation !important;
}

.mobile-input-buttons {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}

.mobile-chat-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
}

.mobile-chat-messages {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  padding-bottom: 140px; /* Space for input + nav */
  /* Smooth scrolling */
  -webkit-overflow-scrolling: touch;
  scroll-behavior: smooth;
}

/* Dark mode support for mobile input */
.dark .mobile-input-container {
  background: #1f2937;
  border-top-color: #374151;
}

.dark .mobile-text-input {
  background: #374151 !important;
  border-color: #4b5563 !important;
  color: #f9fafb !important;
}

/* iOS Safari keyboard fix */
@supports (-webkit-appearance: none) {
  .mobile-input-container {
    /* Force input to stay visible on iOS */
    position: fixed !important;
    bottom: max(60px, calc(env(keyboard-inset-height, 0px) + 60px)) !important;
    /* Prevent viewport shifts */
    -webkit-transform: translateY(0) translateZ(0);
