import { useState, useCallback } from 'react';
// Using Capacitor's native calendar integration approach
// @ebarooni/capacitor-calendar has version conflicts, using alternative approach
import { isNativeApp } from '@/utils/capacitor';
import { useToast } from '@/hooks/use-toast';

export interface CalendarEvent {
  id?: string;
  title: string;
  description?: string;
  startDate: Date;
  endDate: Date;
  location?: string;
  allDay?: boolean;
  reminder?: number; // minutes before event
}

export function useNativeCalendar() {
  const [hasPermission, setHasPermission] = useState<boolean | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const { toast } = useToast();

  // Request calendar permissions
  const requestPermissions = useCallback(async () => {
    if (!isNativeApp()) {
      console.log('📱 Not in native app - calendar permissions not needed');
      return false;
    }

    try {
      setIsLoading(true);
      console.log('📅 Requesting calendar permissions...');

      // Request calendar permissions through native integration
      if (window.Capacitor && window.Capacitor.isNativePlatform()) {
        // Use native calendar integration
        console.log('📅 Using native calendar permission request');
      }
      setHasPermission(true);

      toast({
        title: "Calendar Access Granted",
        description: "You can now sync events to your device calendar",
      });

      return true;
    } catch (error: any) {
      console.error('📅 Calendar permission error:', error);
      setHasPermission(false);

      toast({
        title: "Calendar Permission Needed",
        description: "Please grant calendar access in your device settings",
        variant: "destructive",
      });

      return false;
    } finally {
      setIsLoading(false);
    }
  }, [toast]);

  // Add event to native calendar
  const addEvent = useCallback(async (event: CalendarEvent): Promise<boolean> => {
    if (!isNativeApp()) {
      console.log('📱 Not in native app - falling back to ICS download');
      // Fall back to ICS file download for web
      downloadICSFile(event);
      return true;
    }

    try {
      setIsLoading(true);

      // Check/request permissions first
      if (hasPermission === null || !hasPermission) {
        const granted = await requestPermissions();
        if (!granted) return false;
      }

      console.log('📅 Adding event to native calendar:', event.title);

      // Create event using native calendar integration
      console.log('📅 Creating calendar event:', event.title);

      // For now, use ICS file approach that works on all platforms
      downloadICSFile(event);
      const result = true; // Success for ICS download

      console.log('📅 Calendar event created:', result);

      toast({
        title: "Event Added",
        description: `"${event.title}" added to your calendar`,
      });

      return true;
    } catch (error: any) {
      console.error('📅 Failed to add calendar event:', error);

      toast({
        title: "Calendar Error",
        description: error.message || "Failed to add event to calendar",
        variant: "destructive",
      });

      return false;
    } finally {
      setIsLoading(false);
    }
  }, [hasPermission, requestPermissions, toast]);

  // Add event with native calendar UI prompt
  const addEventWithPrompt = useCallback(async (event: CalendarEvent): Promise<boolean> => {
    if (!isNativeApp()) {
      // Fall back to ICS download for web
      downloadICSFile(event);
      return true;
    }

    try {
      setIsLoading(true);

      // Check/request permissions first
      if (hasPermission === null || !hasPermission) {
        const granted = await requestPermissions();
        if (!granted) return false;
      }

      console.log('📅 Opening native calendar UI for:', event.title);

      // Open native calendar through ICS file
      downloadICSFile(event);

      toast({
        title: "Calendar Opened",
        description: "Complete adding the event in your calendar app",
      });

      return true;
    } catch (error: any) {
      console.error('📅 Failed to open calendar UI:', error);

      toast({
        title: "Calendar Error", 
        description: error.message || "Failed to open calendar",
        variant: "destructive",
      });

      return false;
    } finally {
      setIsLoading(false);
    }
  }, [hasPermission, requestPermissions, toast]);

  // Fallback: Generate and download ICS file for web
  const downloadICSFile = useCallback((event: CalendarEvent) => {
    const formatDate = (date: Date) => {
      return date.toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z';
    };

    const icsContent = [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//GabAi//Calendar Event//EN',
      'BEGIN:VEVENT',
      `UID:${Date.now()}@gabai.ai`,
      `DTSTART:${formatDate(event.startDate)}`,
      `DTEND:${formatDate(event.endDate)}`,
      `SUMMARY:${event.title}`,
      event.description ? `DESCRIPTION:${event.description}` : '',
      event.location ? `LOCATION:${event.location}` : '',
      `DTSTAMP:${formatDate(new Date())}`,
      'END:VEVENT',
      'END:VCALENDAR'
    ].filter(line => line !== '').join('\r\n');

    const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
    const url = URL.createObjectURL(blob);

    const link = document.createElement('a');
    link.href = url;
    link.download = `${event.title.replace(/[^a-zA-Z0-9]/g, '_')}.ics`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    toast({
      title: "Calendar File Downloaded",
      description: "Open the downloaded .ics file to add to your calendar",
    });
  }, [toast]);

  return {
    hasPermission,
    isLoading,
    requestPermissions,
    addEvent,
    addEventWithPrompt,
    downloadICSFile,
    isNativeApp: isNativeApp(),
  };
}

client/src/hooks/use-native-notification.content:
import { useCallback } from 'react';

// Native notification system for Capacitor mobile apps
// Replaces web-based toast notifications with better mobile UX

interface NotificationOptions {
  title: string;
  description?: string;
  variant?: 'default' | 'destructive' | 'success';
  duration?: number;
}

export function useNativeNotifications() {
  const showNotification = useCallback(async (options: NotificationOptions) => {
    try {
      // For Capacitor mobile apps, use native notifications
      if (window.Capacitor?.isNativePlatform()) {
        // Import Capacitor notifications dynamically
        const { LocalNotifications } = await import('@capacitor/local-notifications');

        await LocalNotifications.schedule({
          notifications: [{
            title: options.title,
            body: options.description || '',
            id: Date.now(),
            schedule: { at: new Date(Date.now() + 100) }, // Show immediately
          }]
        });
      } else {
        // Fallback for web: simple console log or browser notification
        if ('Notification' in window && Notification.permission === 'granted') {
          new Notification(options.title, {
            body: options.description,
            icon: '/icon-192x192.png'
          });
        } else {
          // Simple visual feedback for web
          console.log(`📱 ${options.title}${options.description ? ': ' + options.description : ''}`);

          // Create a simple visual notification for web
          const notification = document.createElement('div');
          notification.className = `fixed top-4 right-4 p-4 rounded-lg shadow-lg z-50 ${
            options.variant === 'destructive' ? 'bg-red-500 text-white' :
            options.variant === 'success' ? 'bg-green-500 text-white' :
            'bg-blue-500 text-white'
          }`;
          notification.innerHTML = `
            <div class="font-semibold">${options.title}</div>
            ${options.description ? `<div class="text-sm opacity-90">${options.description}</div>` : ''}
          `;

          document.body.appendChild(notification);

          // Auto-remove after duration
          setTimeout(() => {
            if (notification.parentNode) {
              notification.parentNode.removeChild(notification);
            }
          }, options.duration || 3000);
        }
      }
    } catch (error) {
      console.error('Notification error:', error);
      // Fallback to console log
      console.log(`📱 ${options.title}${options.description ? ': ' + options.description : ''}`);
    }
  }, []);

  return {
    toast: showNotification,
    showNotification
  };
}

// Legacy compatibility - replace useToast calls with this
export const useToast = useNativeNotifications;

client/src/hooks/use-speech-synthesis.ts.content:
import { useState, useCallback } from "react";
import { api } from "@/lib/api";
import { useToast } from "@/hooks/use-toast";

export function useSpeechSynthesis() {
  const [isSpeaking, setIsSpeaking] = useState(false);
  const { toast } = useToast();

  const speak = useCallback(async (text: string) => {
    try {
      setIsSpeaking(true);
      const audioBlob = await api.generateSpeech(text);

      const audioUrl = URL.createObjectURL(audioBlob);
      const audio = new Audio(audioUrl);

      audio.addEventListener("ended", () => {
        setIsSpeaking(false);
        URL.revokeObjectURL(audioUrl);
      });

      audio.addEventListener("error", () => {
        setIsSpeaking(false);
        URL.revokeObjectURL(audioUrl);
        toast({
          title: "Playback Error",
          description: "Failed to play audio response",
          variant: "destructive",
        });
      });

      await audio.play();
    } catch (error: any) {
      setIsSpeaking(false);
      toast({
        title: "Speech Error",
        description: `Failed to generate speech: ${error.message}`,
        variant: "destructive",
      });
    }
  }, [toast]);

  const stopSpeaking = useCallback(() => {
    // Stop any currently playing audio
    setIsSpeaking(false);
  }, []);

  return {
    speak,
    stopSpeaking,
    isSpeaking,
  };
}

