import { QueryClient, QueryFunction } from "@tanstack/react-query";

async function throwIfResNotOk(res: Response) {
  if (!res.ok) {
    const text = (await res.text()) || res.statusText;
    throw new Error(`${res.status}: ${text}`);
  }
}

export async function apiRequest(
  url: string,
  method: string,
  data?: unknown | undefined,
): Promise<Response> {
  // Ensure we use production API for mobile builds
  const apiBase = "https://gabai.ai";
  const fullUrl = url.startsWith('http') ? url : `${apiBase}${url}`;

  console.log('🔗 Query Request:', { originalUrl: url, fullUrl, apiBase });

  const res = await fetch(fullUrl, {
    method,
    headers: data ? { "Content-Type": "application/json" } : {},
    body: data ? JSON.stringify(data) : undefined,
    credentials: "include",
  });

  await throwIfResNotOk(res);
  return res;
}

type UnauthorizedBehavior = "returnNull" | "throw";
export const getQueryFn: <T>(options: {
  on401: UnauthorizedBehavior;
}) => QueryFunction<T> =
  ({ on401: unauthorizedBehavior }) =>
  async ({ queryKey }) => {
    // Handle array query keys properly - first element is path, rest are params
    let url: string;
    if (Array.isArray(queryKey) && queryKey.length > 1) {
      const [basePath, ...params] = queryKey;
      url = `${basePath}/${params.join('/')}`;
    } else {
      url = queryKey.join("/");
    }

    // Ensure we use production API for mobile builds
    const apiBase = "https://gabai.ai";
    const fullUrl = url.startsWith('http') ? url : `${apiBase}${url}`;

    console.log('🔗 API Request:', { originalUrl: url, fullUrl, apiBase });

    const res = await fetch(fullUrl, {
      credentials: "include",
    });

    if (unauthorizedBehavior === "returnNull" && res.status === 401) {
      return null;
    }

    await throwIfResNotOk(res);
    return await res.json();
  };

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      queryFn: getQueryFn({ on401: "throw" }),
      refetchInterval: false,
      refetchOnWindowFocus: false,
      staleTime: Infinity,
      retry: false,
    },
    mutations: {
      retry: false,
    },
  },
});

