                  `;

                  modal.innerHTML = `
                    <div style="
                      background: white;
                      border-radius: 12px;
                      padding: 40px;
                      width: 90%;
                      max-width: 400px;
                      text-align: center;
                      box-shadow: 0 20px 50px rgba(0,0,0,0.5);
                    ">
                      <h2 style="margin: 0 0 20px 0; color: #333;">Welcome to GabAi</h2>
                      <p style="color: #666; margin-bottom: 30px;">Enter your email to continue</p>
