import React, { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useRoute } from "wouter";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Plus, Share2, ExternalLink } from "lucide-react";
import { LogoBubble } from "@/components/ui/logo-spinner";
import { api } from "@/lib/api";
import { useToast } from "@/hooks/use-toast";
import { BottomNav } from "@/components/navigation/bottom-nav";
import type { SmartList, ListItem } from "@shared/schema";
const gabaiLogo = "/gabai-logo.png";

export function SharedListPage() {
  const [, params] = useRoute("/shared/:shareCode");
  const shareCode = params?.shareCode;
  const [newItemName, setNewItemName] = useState("");
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Get shared list
  const { data: sharedList, isLoading, error } = useQuery<SmartList & { items: ListItem[] }>({
    queryKey: ["/api/shared", shareCode],
    enabled: !!shareCode,
    queryFn: () => api.getSharedList(shareCode!),
  });

  // Add item mutation
  const addItemMutation = useMutation({
    mutationFn: (name: string) => api.createListItem({
      listId: sharedList!.id,
      name: name.trim(),
      category: "Other",
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/shared", shareCode] });
      setNewItemName("");
      toast({
        title: "Item Added",
        description: "Item has been added to the shared list.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Failed to Add Item",
        description: error.message || "Could not add item to the list.",
        variant: "destructive",
      });
    },
  });

  // Toggle item mutation
  const toggleItemMutation = useMutation({
    mutationFn: (item: ListItem) => api.updateListItem(item.id, {
      completed: !item.completed,
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/shared", shareCode] });
    },
  });

  const handleAddItem = () => {
    if (newItemName.trim()) {
      addItemMutation.mutate(newItemName);
    }
  };

  const handleToggleItem = (item: ListItem) => {
    toggleItemMutation.mutate(item);
  };

  const groupItemsByCategory = (items: ListItem[]) => {
    const grouped = items.reduce((acc, item) => {
      const category = item.category || "Other";
      if (!acc[category]) acc[category] = [];
      acc[category].push(item);
      return acc;
    }, {} as Record<string, ListItem[]>);

    return grouped;
  };

  if (isLoading) {
    return (
      <div className="container mx-auto p-4 max-w-2xl">
        <Skeleton className="h-8 w-64 mb-4" />
        <Skeleton className="h-32 w-full mb-4" />
        <Skeleton className="h-32 w-full" />
      </div>
    );
  }

  if (error || !sharedList) {
    return (
      <div className="container mx-auto p-4 max-w-2xl">
        <Card>
          <CardContent className="p-6 text-center">
            <h2 className="text-xl font-semibold mb-2">List Not Found</h2>
            <p className="text-gray-600 dark:text-gray-400 mb-4">
              The shared list you're looking for doesn't exist or has been removed.
            </p>
            <Button onClick={() => window.location.href = "/"}>
              Go to Home
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const groupedItems = groupItemsByCategory(sharedList.items);
  const completedCount = sharedList.items.filter(item => item.completed).length;

  return (
    <div className="container mx-auto p-4 max-w-2xl">
      {/* Header */}
      <div className="mb-6">
        <div className="flex items-center gap-2 mb-2">
          <LogoBubble size="sm" />
          <span className="text-sm font-medium text-blue-500">Shared List</span>
        </div>
        <h1 className="text-2xl font-bold">{sharedList.name}</h1>
        <p className="text-gray-600 dark:text-gray-400">
          {completedCount} of {sharedList.items.length} completed
        </p>
      </div>

      {/* Add Item */}
      <Card className="mb-6">
        <CardContent className="p-4">
          <div className="flex items-center space-x-2">
            <Input
              value={newItemName}
              onChange={(e) => setNewItemName(e.target.value)}
              placeholder="Add item to shared list..."
              className="smart-list-input"
              style={{ 
                fontSize: '16px',
                minHeight: '44px',
                direction: 'ltr',
                unicodeBidi: 'normal',
                textAlign: 'left'
              }}
              onKeyPress={(e) => {
                if (e.key === "Enter") {
                  handleAddItem();
                }
              }}
            />
            <Button
              onClick={handleAddItem}
              disabled={!newItemName.trim() || addItemMutation.isPending}
              size="sm"
              className="w-10 h-10 p-0"
            >
              <Plus className="h-4 w-4" />
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Items by Category */}
      <div className="space-y-4">
        {Object.entries(groupedItems).map(([category, items]) => (
          <Card key={category}>
            <CardHeader className="pb-3">
              <CardTitle className="text-base capitalize">{category}</CardTitle>
            </CardHeader>
            <CardContent className="space-y-2">
              {items.map((item) => (
                <div
                  key={item.id}
                  className="flex items-center space-x-3 p-2 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-800"
                >
                  <Checkbox
                    checked={item.completed || false}
                    onCheckedChange={() => handleToggleItem(item)}
                  />
                  <span
                    className={`flex-1 ${
                      item.completed
                        ? "line-through text-gray-500 dark:text-gray-400"
                        : "text-gray-900 dark:text-white"
                    }`}
                    style={{ 
                      unicodeBidi: 'plaintext',
                      textAlign: 'start'
                    }}
                  >
                    {item.name}
                  </span>
                </div>
              ))}
            </CardContent>
          </Card>
        ))}

        {sharedList.items.length === 0 && (
          <Card>
            <CardContent className="p-8 text-center">
              <p className="text-gray-500 dark:text-gray-400">
                This list is empty. Add the first item above!
              </p>
            </CardContent>
          </Card>
        )}
      </div>

      {/* Footer */}
      <div className="mt-8 text-center">
        <p className="text-sm text-gray-500 dark:text-gray-400 mb-2">
          Powered by GabAi
        </p>
        <div className="flex items-center gap-2 justify-center mb-3">
          <img 
            src={gabaiLogo} 
            alt="GabAi" 
            className="w-6 h-6 object-contain"
          />
          <span className="text-sm font-medium text-gray-600 dark:text-gray-400">
            Powered by GabAi
          </span>
        </div>
        <Button variant="outline" size="sm" onClick={() => window.location.href = "/"}>
          <ExternalLink className="h-4 w-4 mr-2" />
          Get Your Own Smart Lists
        </Button>
      </div>

      {/* Bottom Navigation */}
      <div className="h-20" />
      <div className="fixed bottom-0 left-0 right-0 z-50">
        <BottomNav />
      </div>
    </div>
  );
}

client/src/pages/simple-login.tsx.content:
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useMutation } from "@tanstack/react-query";
import { User, Mail, ArrowRight } from "lucide-react";
const gabaiLogo = "/gabai-logo.png";

export default function SimpleLoginPage() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const { toast } = useToast();

  const loginMutation = useMutation({
    mutationFn: async ({ name, email }: { name: string; email: string }) => {
      const response = await fetch("/api/simple-login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ name, email }),
        credentials: "include", // Important for session cookies
      });

      if (!response.ok) {
        const error = await response.json().catch(() => ({ message: "Login failed" }));
        throw new Error(error.message || "Login failed");
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/auth/user"] });
      toast({
        title: "Welcome to GabAi!",
        description: "Let's get you set up with your personal assistant.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Login failed",
        description: error.message || "Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || !email.trim()) {
      toast({
        title: "Please fill in all fields",
        description: "Name and email are required to continue.",
        variant: "destructive",
      });
      return;
    }
    loginMutation.mutate({ name: name.trim(), email: email.trim() });
  };

  const tryGoogleLogin = () => {
    window.location.href = "/api/auth/google";
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-100 dark:from-gray-900 dark:to-gray-800 p-4">
      <Card className="w-full max-w-md">
        <CardHeader className="text-center space-y-4">
          <div className="mx-auto w-16 h-16 flex items-center justify-center">
            <img 
              src={gabaiLogo} 
              alt="GabAi" 
              className="w-full h-full object-contain"
            />
          </div>
          <div>
            <CardTitle className="text-2xl font-bold">Welcome to GabAi</CardTitle>
            <p className="text-gray-600 dark:text-gray-300 mt-2">
              Your intelligent voice-first personal assistant
            </p>
          </div>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Simple Login Form */}
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="name" className="flex items-center space-x-2">
                <User className="h-4 w-4" />
                <span>Your Name</span>
              </Label>
              <Input
                id="name"
                type="text"
                placeholder="Enter your name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="email" className="flex items-center space-x-2">
                <Mail className="h-4 w-4" />
                <span>Email Address</span>
              </Label>
              <Input
                id="email"
                type="email"
                placeholder="Enter your email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>

            <Button 
              type="submit" 
              className="w-full" 
              disabled={loginMutation.isPending}
            >
              {loginMutation.isPending ? (
                "Getting Started..."
              ) : (
                <>
                  Get Started
                  <ArrowRight className="ml-2 h-4 w-4" />
                </>
              )}
            </Button>
          </form>

          {/* Divider */}
          <div className="relative">
            <div className="absolute inset-0 flex items-center">
              <span className="w-full border-t" />
            </div>
            <div className="relative flex justify-center text-xs uppercase">
              <span className="bg-background px-2 text-muted-foreground">
                Or continue with
              </span>
            </div>
          </div>

          {/* Google OAuth Option */}
          <Button 
            variant="outline" 
            className="w-full" 
            onClick={tryGoogleLogin}
          >
            <svg className="mr-2 h-4 w-4" viewBox="0 0 24 24">
              <path
                fill="currentColor"
                d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
              />
              <path
                fill="currentColor"
                d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
              />
              <path
                fill="currentColor"
                d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
              />
              <path
                fill="currentColor"
                d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
              />
            </svg>
            Continue with Google
          </Button>

