import { useState, useRef, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { VoiceInput } from "./voice-input";
import { MessageBubble } from "./message-bubble";
import { TypingIndicator } from "./typing-indicator";
import { useAuth } from "@/hooks/useAuth";
import { queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import type { Message } from "@shared/schema";
import { api } from "@/lib/api";

export function ChatInterface() {
  const { user } = useAuth();
  const { toast } = useToast();
  const [currentConversationId, setCurrentConversationId] = useState<string | null>(() => {
    if (typeof window !== "undefined" && user) {
      return localStorage.getItem(`gabai_conversation_${user.id}`) || null;
    }
    return null;
  });

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Get messages for current conversation
  const messagesQuery = useQuery({
    queryKey: ["/api/messages", currentConversationId],
    queryFn: async () => {
      if (!currentConversationId) return [];
      return api.getMessages(currentConversationId);
    },
    enabled: !!currentConversationId,
  });

  const messages = messagesQuery.data || [];
  const isLoading = messagesQuery.isLoading;

  // Send message mutation
  const sendMessageMutation = useMutation({
    mutationFn: async (message: string) => {
      if (!user) throw new Error("User not authenticated");

      // Create conversation if needed
      if (!currentConversationId) {
        const newConversation = await api.createConversation({ userId: user.id });
        setCurrentConversationId(newConversation.id);
        localStorage.setItem(`gabai_conversation_${user.id}`, newConversation.id);
      }

      return api.sendMessage(message, user.id, currentConversationId!);
    },
    onSuccess: (response) => {
      setCurrentConversationId(response.conversationId);
      if (user) {
        localStorage.setItem(`gabai_conversation_${user.id}`, response.conversationId);

        // Update messages cache
        queryClient.setQueryData(
          ["/api/messages", response.conversationId],
          (oldMessages: Message[] = []) => {
            const hasTemp = oldMessages.some(msg => msg.id.toString().startsWith('temp-'));
            if (hasTemp) {
              const filteredMessages = oldMessages.filter(msg => !msg.id.toString().startsWith('temp-'));
              return [...filteredMessages, response.message];
            }
            return [...oldMessages, response.message];
          }
        );

        // Invalidate caches if AI performed actions
        if (response.actions && response.actions.length > 0) {
          queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
        }
        queryClient.invalidateQueries({ queryKey: ["/api/reminders", user.id] });
      }

      // Show suggestions
      if (response.suggestions && response.suggestions.length > 0) {
        toast({
          title: "Suggestions",
          description: response.suggestions.join(", "),
        });
      }
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to send message",
        variant: "destructive",
      });
    },
  });

  const handleSendMessage = (message: string) => {
    if (sendMessageMutation.isPending || !message.trim()) return;

    // Always add temporary user message to show immediately
    const tempMessage = {
      id: `temp-${Date.now()}`,
      content: message,
      role: 'user' as const,
      createdAt: new Date(),
      conversationId: currentConversationId || 'temp',
      audioUrl: null
    };

    // Update messages immediately for better UX
    if (currentConversationId) {
      queryClient.setQueryData(
        ["/api/messages", currentConversationId],
        (oldMessages: Message[] = []) => [...oldMessages, tempMessage]
      );
    } else {
      // For new conversations, create temporary messages array
      queryClient.setQueryData(
        ["/api/messages", null],
        [tempMessage]
      );
    }

    sendMessageMutation.mutate(message);
  };

  // Auto scroll to bottom - enhanced for mobile
  useEffect(() => {
    const scrollToBottom = () => {
      const container = document.getElementById('chat-messages-container');
      const scrollElement = messagesEndRef.current;

      if (container && scrollElement) {
        // Multiple scroll strategies for different mobile environments

        // Strategy 1: Scroll container to bottom
        container.scrollTop = container.scrollHeight;

        // Strategy 2: Use scrollIntoView
        scrollElement.scrollIntoView({ behavior: "smooth", block: "end" });

        // Strategy 3: Delayed scroll for mobile rendering
        setTimeout(() => {
          container.scrollTop = container.scrollHeight;
          scrollElement.scrollIntoView({ behavior: "auto", block: "end" });
        }, 100);

        // Strategy 4: Force scroll for mobile WebView
        setTimeout(() => {
          container.scrollTop = container.scrollHeight;
        }, 300);
      }
    };

    scrollToBottom();
  }, [messages, sendMessageMutation.isPending]);

  if (!user) {
    return (
      <div className="flex items-center justify-center h-full">
        <p className="text-gray-500">Please sign in to start chatting</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-white dark:bg-gray-900">
      {/* Chat messages - simplified layout */}
      <div 
        className="flex-1 overflow-y-auto p-4 space-y-3" 
        id="chat-messages-container"
        style={{ paddingBottom: '40px' }}
      >
        {isLoading ? (
          <div className="flex justify-center py-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
          </div>
        ) : messages.length === 0 ? (
          <div className="text-center py-8 text-gray-500">
            <p>Start a conversation with GabAi!</p>
            <p className="text-sm mt-2">Try asking about lists, reminders, or scheduling</p>
          </div>
        ) : (
          messages.map((message) => (
            <MessageBubble 
              key={message.id} 
              message={message} 
              isUser={message.role === 'user'} 
            />
          ))
        )}

        {sendMessageMutation.isPending && <TypingIndicator />}
        <div ref={messagesEndRef} />
      </div>

      {/* Voice input - proper spacing for mobile bottom nav */}
      <div className="flex-shrink-0 p-4 border-t border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 pb-20">
        <VoiceInput 
          onSendMessage={handleSendMessage}
          disabled={sendMessageMutation.isPending}
        />
      </div>
    </div>
  );
}

client/src/components/chat/enhanced-gaba.content:
import { useState, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { useEnhancedGabAi } from "@/hooks/use-enhanced-gabai";
import { api } from "@/lib/api";
import { ChatInterface } from "./chat-interface";

export function EnhancedGabAiChat() {
  const { user } = useAuth();
  const { analyzeUserRequest, executeGabAiAction, isProcessing } = useEnhancedGabAi();

  // Get user's lists and items
  const { data: lists = [] } = useQuery({
    queryKey: ["/api/smart-lists", user?.id],
    enabled: !!user,
    queryFn: () => api.getSmartLists(user!.id),
  });

  const { data: allItems = [] } = useQuery({
    queryKey: ["/api/all-list-items", user?.id],
    enabled: !!user && lists.length > 0,
    queryFn: async () => {
      if (!user) return [];
      const itemPromises = lists.map(list => api.getListItems(list.id));
      const itemArrays = await Promise.all(itemPromises);
      return itemArrays.flat();
    },
  });

  // Enhanced message handler that processes list actions
  const handleMessage = async (message: string) => {
    if (!user) return;

    // Check if this is a list-related command
    const listKeywords = ['add', 'remove', 'delete', 'buy', 'get', 'need', 'list', 'todo', 'task', 'fix', 'repair'];
    const isListCommand = listKeywords.some(keyword => message.toLowerCase().includes(keyword));

    if (isListCommand) {
      const action = analyzeUserRequest(message, lists);
      await executeGabAiAction(action, lists, allItems);

      // Return a response based on the action
      switch (action.action) {
        case 'add':
          return `I added "${action.itemText}" to your ${action.listName} list.`;
        case 'remove':
          return `I'm looking for "${action.itemText}" to remove from your lists.`;
        case 'create_list':
          return `I created a new ${action.listType?.replace('-', ' ')} list called "${action.listName}" and added "${action.itemText}".`;
        default:
          return "I processed your list request.";
      }
    }

    // For non-list commands, use regular chat
    return null; // Let the regular chat interface handle it
  };

  return (
    <ChatInterface 
      onMessage={handleMessage}
      isProcessingListAction={isProcessing}
    />
  );
}

