import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { User, Download, Phone, Mail, Building, MapPin, Calendar, ArrowLeft, Home, Edit, Trash2, Plus } from "lucide-react";
import { Link } from "wouter";
import { useAuth } from "@/hooks/useAuth";
import { api } from "@/lib/api";
import { useToast } from "@/hooks/use-toast";
import { BottomNav } from "@/components/navigation/bottom-nav";

interface Contact {
  id: string;
  firstName?: string;
  lastName?: string;
  company?: string;
  jobTitle?: string;
  email?: string;
  phone?: string;
  website?: string;
  address?: string;
  notes?: string;
  source?: string;
  createdAt: string;
}

export function ContactsPage() {
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [editingContact, setEditingContact] = useState<Contact | null>(null);
  const [deletingContact, setDeletingContact] = useState<Contact | null>(null);

  const { data: contacts = [], isLoading } = useQuery({
    queryKey: ["/api/contacts", user?.id],
    enabled: !!user?.id,
    queryFn: () => api.getContacts(user!.id),
  });

  // Update contact mutation
  const updateContactMutation = useMutation({
    mutationFn: (contact: Contact) => api.updateContact(contact.id, contact),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/contacts", user?.id] });
      setEditingContact(null);
      toast({
        title: "Contact Updated",
        description: "Contact has been successfully updated.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Update Failed",
        description: error.message || "Failed to update contact.",
        variant: "destructive",
      });
    },
  });

  // Delete contact mutation
  const deleteContactMutation = useMutation({
    mutationFn: (contactId: string) => api.deleteContact(contactId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/contacts", user?.id] });
      setDeletingContact(null);
      toast({
        title: "Contact Deleted",
        description: "Contact has been successfully deleted.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Delete Failed",
        description: error.message || "Failed to delete contact.",
        variant: "destructive",
      });
    },
  });

  const downloadVCard = async (contactId: string, contactName: string) => {
    try {
      api.downloadVCard(contactId);
      toast({
        title: "VCard Downloaded",
        description: `Contact card for ${contactName} has been downloaded.`,
      });
    } catch (error: any) {
      toast({
        title: "Download Failed",
        description: error.message,
        variant: "destructive",
      });
    }
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        {/* Navigation Header */}
        <div className="flex items-center justify-between border-b pb-4">
          <Link href="/">
            <Button variant="ghost" size="sm" className="flex items-center space-x-2">
              <ArrowLeft className="h-4 w-4" />
              <span>Back to Home</span>
            </Button>
          </Link>
          <h1 className="text-2xl font-bold">Contacts</h1>
          <div className="w-20"></div> {/* Spacer for balance */}
        </div>

        <div className="text-center py-8">
          <User className="h-12 w-12 mx-auto text-gray-400 mb-4" />
          <p>Loading your contacts...</p>
        </div>

        {/* Bottom Navigation */}
        <div className="h-20" />
        <div className="fixed bottom-0 left-0 right-0 z-50">
          <BottomNav />
        </div>
      </div>
    );
  }

  if (contacts.length === 0) {
    return (
      <div className="space-y-6">
        {/* Navigation Header */}
        <div className="flex items-center justify-between border-b pb-4">
          <Link href="/">
            <Button variant="ghost" size="sm" className="flex items-center space-x-2">
              <ArrowLeft className="h-4 w-4" />
              <span>Back to Home</span>
            </Button>
          </Link>
          <h1 className="text-2xl font-bold">Contacts</h1>
          <div className="w-20"></div> {/* Spacer for balance */}
        </div>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center space-x-2">
              <User className="h-5 w-5" />
              <span>Contacts</span>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-center py-8">
              <User className="h-12 w-12 mx-auto text-gray-400 mb-4" />
              <h3 className="text-lg font-medium mb-2">No contacts yet</h3>
              <p className="text-gray-600 dark:text-gray-300 mb-4">
                Start by uploading business cards or images with contact information in the OCR section.
              </p>
              <Badge variant="secondary">Business cards will automatically create contacts</Badge>
            </div>
          </CardContent>
        </Card>

        {/* Bottom Navigation */}
        <div className="h-20" />
        <div className="fixed bottom-0 left-0 right-0 z-50">
          <BottomNav />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col">
      {/* Navigation Header */}
      <div className="flex items-center justify-between border-b pb-4 px-4 pt-4">
        <Link href="/">
          <Button variant="ghost" size="sm" className="flex items-center space-x-2">
            <ArrowLeft className="h-4 w-4" />
            <span>Back to Home</span>
          </Button>
        </Link>
        <h1 className="text-2xl font-bold">Contacts</h1>
        <Badge variant="outline">{contacts.length}</Badge>
      </div>

      {/* Scrollable Contacts List */}
      <div className="flex-1 overflow-y-auto px-4 py-4 pb-32 mobile-page mobile-content">
        <div className="space-y-4">
          {contacts.map((contact: Contact) => (
            <Card key={contact.id} className="hover:shadow-md transition-shadow">
              <CardContent className="p-4">
                <div className="space-y-3">
                  {/* Header with Name and Actions */}
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <h3 className="font-medium text-lg">
                        {contact.firstName || contact.lastName 
                          ? `${contact.firstName || ''} ${contact.lastName || ''}`.trim()
                          : 'Contact'
                        }
                      </h3>
                      {contact.jobTitle && contact.company && (
                        <p className="text-sm text-gray-600 dark:text-gray-300">
                          {contact.jobTitle} at {contact.company}
                        </p>
                      )}
                      {contact.jobTitle && !contact.company && (
                        <p className="text-sm text-gray-600 dark:text-gray-300">
                          {contact.jobTitle}
                        </p>
                      )}
                      {!contact.jobTitle && contact.company && (
                        <p className="text-sm text-gray-600 dark:text-gray-300">
                          {contact.company}
                        </p>
                      )}
                    </div>

                    {/* Action Buttons */}
                    <div className="flex items-center space-x-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setEditingContact(contact)}
                        className="smart-list-button"
                        title="Edit contact"
                      >
                        <Edit className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => downloadVCard(
                          contact.id,
                          `${contact.firstName || ''} ${contact.lastName || ''}`.trim() || 'Contact'
                        )}
                        className="smart-list-button"
                        title="Download vCard"
                      >
                        <Download className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setDeletingContact(contact)}
                        className="text-red-600 hover:text-red-700 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-900/20 smart-list-button"
                        title="Delete contact"
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>

                  {/* Contact Information */}
                  <div className="space-y-2">
                    {contact.email && (
                      <div className="flex items-center space-x-2 text-sm">
                        <Mail className="h-4 w-4 text-gray-400" />
                        <a href={`mailto:${contact.email}`} className="hover:underline">
                          {contact.email}
                        </a>
                      </div>
                    )}

                    {contact.phone && (
                      <div className="flex items-center space-x-2 text-sm">
                        <Phone className="h-4 w-4 text-gray-400" />
                        <a href={`tel:${contact.phone}`} className="hover:underline">
                          {contact.phone}
                        </a>
                      </div>
                    )}

                    {contact.address && (
                      <div className="flex items-center space-x-2 text-sm">
                        <MapPin className="h-4 w-4 text-gray-400" />
                        <span className="truncate">{contact.address}</span>
                      </div>
                    )}

                    {contact.notes && (
                      <div className="text-sm text-gray-600 dark:text-gray-300 bg-gray-50 dark:bg-gray-800 rounded p-2">
                        {contact.notes}
                      </div>
                    )}
                  </div>

                  {/* Footer */}
                  <div className="flex items-center justify-between pt-2 border-t">
                    <div className="flex items-center space-x-2 text-xs text-gray-500">
                      <Calendar className="h-3 w-3" />
                      <span>{new Date(contact.createdAt).toLocaleDateString()}</span>
                    </div>
                    {contact.source === 'business_card' && (
                      <Badge variant="secondary" className="text-xs">
                        Business Card
                      </Badge>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>

      {/* Edit Contact Dialog */}
      {editingContact && (
        <Dialog open={!!editingContact} onOpenChange={() => setEditingContact(null)}>
          <DialogContent className="max-w-md max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>Edit Contact</DialogTitle>
            </DialogHeader>
            <ContactForm 
              contact={editingContact}
              onSave={(updatedContact) => updateContactMutation.mutate(updatedContact)}
              onCancel={() => setEditingContact(null)}
              isLoading={updateContactMutation.isPending}
            />
          </DialogContent>
        </Dialog>
      )}

      {/* Delete Confirmation Dialog */}
      {deletingContact && (
        <Dialog open={!!deletingContact} onOpenChange={() => setDeletingContact(null)}>
          <DialogContent className="max-w-md">
            <DialogHeader>
              <DialogTitle>Delete Contact</DialogTitle>
            </DialogHeader>
            <div className="space-y-4">
              <p className="text-gray-600 dark:text-gray-300">
                Are you sure you want to delete{' '}
                <span className="font-medium">
                  {deletingContact.firstName || deletingContact.lastName 
                    ? `${deletingContact.firstName || ''} ${deletingContact.lastName || ''}`.trim()
                    : 'this contact'
                  }
                </span>
                ? This action cannot be undone.
              </p>
              <div className="flex space-x-3 justify-end">
                <Button
                  variant="outline"
                  onClick={() => setDeletingContact(null)}
                  disabled={deleteContactMutation.isPending}
                >
                  Cancel
                </Button>
                <Button
                  variant="destructive"
                  onClick={() => deleteContactMutation.mutate(deletingContact.id)}
                  disabled={deleteContactMutation.isPending}
                  className="smart-list-button"
                >
                  {deleteContactMutation.isPending ? "Deleting..." : "Delete"}
                </Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      )}

      {/* Bottom Navigation */}
      <div className="fixed bottom-0 left-0 right-0 z-50">
        <BottomNav />
      </div>
    </div>
  );
}

// Contact Form Component
interface ContactFormProps {
  contact: Contact;
  onSave: (contact: Contact) => void;
  onCancel: () => void;
  isLoading: boolean;
}

function ContactForm({ contact, onSave, onCancel, isLoading }: ContactFormProps) {
  const [formData, setFormData] = useState({
    firstName: contact.firstName || '',
    lastName: contact.lastName || '',
    company: contact.company || '',
    jobTitle: contact.jobTitle || '',
    email: contact.email || '',
    phone: contact.phone || '',
    website: contact.website || '',
    address: contact.address || '',
    notes: contact.notes || '',
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...contact,
      ...formData,
    });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="grid grid-cols-2 gap-3">
        <div>
          <Label htmlFor="firstName" className="text-sm font-medium">First Name</Label>
          <Input
            id="firstName"
            value={formData.firstName}
            onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
            className="smart-list-button"
          />
        </div>
        <div>
          <Label htmlFor="lastName" className="text-sm font-medium">Last Name</Label>
          <Input
            id="lastName"
            value={formData.lastName}
            onChange={(e) => setFormData({ ...formData, lastName: e.target.value })}
            className="smart-list-button"
          />
        </div>
      </div>

      <div>
        <Label htmlFor="company" className="text-sm font-medium">Company</Label>
        <Input
          id="company"
          value={formData.company}
          onChange={(e) => setFormData({ ...formData, company: e.target.value })}
          className="smart-list-button"
        />
      </div>

      <div>
        <Label htmlFor="jobTitle" className="text-sm font-medium">Job Title</Label>
        <Input
          id="jobTitle"
          value={formData.jobTitle}
          onChange={(e) => setFormData({ ...formData, jobTitle: e.target.value })}
          className="smart-list-button"
        />
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div>
          <Label htmlFor="email" className="text-sm font-medium">Email</Label>
          <Input
            id="email"
            type="email"
            value={formData.email}
            onChange={(e) => setFormData({ ...formData, email: e.target.value })}
            className="smart-list-button"
          />
        </div>
        <div>
          <Label htmlFor="phone" className="text-sm font-medium">Phone</Label>
          <Input
            id="phone"
            type="tel"
            value={formData.phone}
            onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
            className="smart-list-button"
          />
        </div>
      </div>

      <div>
        <Label htmlFor="website" className="text-sm font-medium">Website</Label>
        <Input
          id="website"
          type="url"
          value={formData.website}
          onChange={(e) => setFormData({ ...formData, website: e.target.value })}
          className="smart-list-button"
        />
      </div>

      <div>
        <Label htmlFor="address" className="text-sm font-medium">Address</Label>
        <Input
          id="address"
          value={formData.address}
          onChange={(e) => setFormData({ ...formData, address: e.target.value })}
          className="smart-list-button"
        />
      </div>

      <div>
        <Label htmlFor="notes" className="text-sm font-medium">Notes</Label>
        <Textarea
          id="notes"
          value={formData.notes}
          onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
          rows={3}
          className="smart-list-button"
        />
      </div>

      <div className="flex space-x-3 justify-end pt-4">
        <Button
          type="button"
          variant="outline"
          onClick={onCancel}
          disabled={isLoading}
        >
          Cancel
        </Button>
        <Button
          type="submit"
          disabled={isLoading}
          className="smart-list-button"
        >
          {isLoading ? "Saving..." : "Save Changes"}
        </Button>
      </div>
    </form>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { User, Download, Phone, Mail, Building, MapPin, Calendar, ArrowLeft, Home, Edit, Trash2, Plus } from "lucide-react";
import { Link } from "wouter";
import { useAuth } from "@/hooks/useAuth";
import { api } from "@/lib/api";
import { useToast } from "@/hooks/use-toast";
import { BottomNav } from "@/components/navigation/bottom-nav";

interface Contact {
  id: string;
  firstName?: string;
  lastName?: string;
  company?: string;
  jobTitle?: string;
  email?: string;
  phone?: string;
  website?: string;
  address?: string;
  notes?: string;
  source?: string;
  createdAt: string;
}

export function ContactsPage() {
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [editingContact, setEditingContact] = useState<Contact | null>(null);
  const [deletingContact, setDeletingContact] = useState<Contact | null>(null);

  const { data: contacts = [], isLoading } = useQuery({
    queryKey: ["/api/contacts", user?.id],
    enabled: !!user?.id,
    queryFn: () => api.getContacts(user!.id),
  });

  // Update contact mutation
  const updateContactMutation = useMutation({
    mutationFn: (contact: Contact) => api.updateContact(contact.id, contact),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/contacts", user?.id] });
      setEditingContact(null);
      toast({
        title: "Contact Updated",
        description: "Contact has been successfully updated.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Update Failed",
        description: error.message || "Failed to update contact.",
        variant: "destructive",
      });
    },
  });

  // Delete contact mutation
  const deleteContactMutation = useMutation({
    mutationFn: (contactId: string) => api.deleteContact(contactId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/contacts", user?.id] });
      setDeletingContact(null);
      toast({
        title: "Contact Deleted",
        description: "Contact has been successfully deleted.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Delete Failed",
        description: error.message || "Failed to delete contact.",
        variant: "destructive",
      });
    },
  });

  const downloadVCard = async (contactId: string, contactName: string) => {
    try {
      api.downloadVCard(contactId);
      toast({
        title: "VCard Downloaded",
        description: `Contact card for ${contactName} has been downloaded.`,
      });
    } catch (error: any) {
      toast({
        title: "Download Failed",
        description: error.message,
        variant: "destructive",
      });
    }
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 dark:bg-gray-900">
      {/* Fixed Header */}
      <div className="flex items-center justify-between p-4 bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 flex-shrink-0">
        <div className="flex items-center space-x-3">
          <Link href="/">
            <Button variant="ghost" size="sm" className="p-2" data-testid="back-button">
              <ArrowLeft className="h-5 w-5" />
            </Button>
          </Link>
          <h1 className="text-2xl font-bold flex items-center space-x-2">
            <User className="h-6 w-6" />
            <span>Contacts</span>
          </h1>
        </div>
        <Button
          onClick={() => setEditingContact({ 
            id: '', firstName: '', lastName: '', company: '', jobTitle: '', 
            email: '', phone: '', website: '', address: '', notes: '', 
            source: 'manual', createdAt: new Date().toISOString() 
          })}
          className="flex items-center space-x-2"
          data-testid="add-contact-button"
        >
          <Plus className="h-4 w-4" />
          <span>Add</span>
        </Button>
      </div>

      {/* Scrollable Content */}
      <div 
        className="flex-1 overflow-y-auto p-4 space-y-4 pb-24" 
        style={{ 
          WebkitOverflowScrolling: 'touch',
          overscrollBehavior: 'contain'
        }}
      >
        {isLoading ? (
          <div className="text-center py-8">
            <User className="h-12 w-12 mx-auto text-gray-400 mb-4" />
            <p>Loading your contacts...</p>
          </div>
        ) : contacts.length === 0 ? (
          <Card>
            <CardContent className="text-center py-8">
              <User className="h-12 w-12 mx-auto text-gray-400 mb-4" />
              <h3 className="text-lg font-medium mb-2">No contacts yet</h3>
              <p className="text-gray-600 dark:text-gray-400 mb-4">
                Start building your network by adding contacts or scanning business cards.
              </p>
              <Button 
                onClick={() => setEditingContact({ 
                  id: '', firstName: '', lastName: '', company: '', jobTitle: '', 
                  email: '', phone: '', website: '', address: '', notes: '', 
                  source: 'manual', createdAt: new Date().toISOString() 
                })}
                className="mx-auto"
              >
                Add Your First Contact
              </Button>
            </CardContent>
          </Card>
        ) : (
          contacts.map((contact) => (
            <Card key={contact.id} className="hover:shadow-md transition-shadow" data-testid={`contact-card-${contact.id}`}>
              <CardHeader className="pb-3">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <CardTitle className="text-lg flex items-center space-x-2">
                      <User className="h-5 w-5 text-blue-500" />
                      <span>{[contact.firstName, contact.lastName].filter(Boolean).join(' ') || 'Unnamed Contact'}</span>
                    </CardTitle>
                    {contact.company && (
                      <div className="flex items-center space-x-1 text-sm text-gray-600 dark:text-gray-400 mt-1">
                        <Building className="h-4 w-4" />
                        <span>{contact.company}</span>
                        {contact.jobTitle && <span> - {contact.jobTitle}</span>}
                      </div>
                    )}
                  </div>
                  <div className="flex items-center space-x-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setEditingContact(contact)}
                      data-testid={`edit-contact-${contact.id}`}
                    >
                      <Edit className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setDeletingContact(contact)}
                      className="text-red-600 hover:text-red-700"
                      data-testid={`delete-contact-${contact.id}`}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="grid grid-cols-1 gap-2 text-sm">
                  {contact.email && (
                    <div className="flex items-center space-x-2">
                      <Mail className="h-4 w-4 text-gray-500" />
                      <a href={`mailto:${contact.email}`} className="text-blue-600 hover:underline">
                        {contact.email}
                      </a>
                    </div>
                  )}
                  {contact.phone && (
                    <div className="flex items-center space-x-2">
                      <Phone className="h-4 w-4 text-gray-500" />
                      <a href={`tel:${contact.phone}`} className="text-blue-600 hover:underline">
                        {contact.phone}
                      </a>
                    </div>
                  )}
                  {contact.address && (
                    <div className="flex items-center space-x-2">
                      <MapPin className="h-4 w-4 text-gray-500" />
                      <span className="text-gray-700 dark:text-gray-300">{contact.address}</span>
                    </div>
                  )}
                </div>

                {contact.notes && (
                  <div className="mt-3 p-3 bg-gray-50 dark:bg-gray-800 rounded-lg">
                    <p className="text-sm text-gray-700 dark:text-gray-300">{contact.notes}</p>
                  </div>
                )}

                <div className="flex items-center justify-between pt-3 border-t">
                  <div className="flex items-center space-x-2">
                    {contact.source && (
                      <Badge variant="secondary" className="text-xs">
                        {contact.source}
                      </Badge>
                    )}
                    <span className="text-xs text-gray-500">
                      <Calendar className="h-3 w-3 inline mr-1" />
                      {new Date(contact.createdAt).toLocaleDateString()}
                    </span>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => downloadVCard(contact.id, [contact.firstName, contact.lastName].filter(Boolean).join(' '))}
                    data-testid={`download-vcard-${contact.id}`}
                  >
                    <Download className="h-4 w-4" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))
        )}
      </div>

      {/* Fixed Bottom Navigation */}
      <div className="flex-shrink-0">
        <BottomNav />
      </div>

      {/* Edit Contact Dialog */}
      {editingContact && (
        <Dialog open={!!editingContact} onOpenChange={() => setEditingContact(null)}>
          <DialogContent className="max-w-md">
            <DialogHeader>
              <DialogTitle>{editingContact.id ? 'Edit Contact' : 'Add New Contact'}</DialogTitle>
            </DialogHeader>
            <div className="space-y-4 max-h-96 overflow-y-auto">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="firstName">First Name</Label>
                  <Input
                    id="firstName"
                    value={editingContact.firstName || ''}
                    onChange={(e) => setEditingContact({...editingContact, firstName: e.target.value})}
                    data-testid="input-first-name"
                  />
                </div>
                <div>
                  <Label htmlFor="lastName">Last Name</Label>
                  <Input
                    id="lastName"
                    value={editingContact.lastName || ''}
                    onChange={(e) => setEditingContact({...editingContact, lastName: e.target.value})}
                    data-testid="input-last-name"
                  />
                </div>
              </div>
              <div>
                <Label htmlFor="email">Email</Label>
                <Input
                  id="email"
                  type="email"
                  value={editingContact.email || ''}
                  onChange={(e) => setEditingContact({...editingContact, email: e.target.value})}
                  data-testid="input-email"
                />
              </div>
              <div>
                <Label htmlFor="phone">Phone</Label>
                <Input
                  id="phone"
                  type="tel"
                  value={editingContact.phone || ''}
                  onChange={(e) => setEditingContact({...editingContact, phone: e.target.value})}
                  data-testid="input-phone"
                />
              </div>
              <div>
                <Label htmlFor="company">Company</Label>
                <Input
                  id="company"
                  value={editingContact.company || ''}
                  onChange={(e) => setEditingContact({...editingContact, company: e.target.value})}
                  data-testid="input-company"
                />
              </div>
              <div>
                <Label htmlFor="jobTitle">Job Title</Label>
                <Input
                  id="jobTitle"
                  value={editingContact.jobTitle || ''}
                  onChange={(e) => setEditingContact({...editingContact, jobTitle: e.target.value})}
                  data-testid="input-job-title"
                />
              </div>
              <div>
                <Label htmlFor="address">Address</Label>
                <Textarea
                  id="address"
                  value={editingContact.address || ''}
                  onChange={(e) => setEditingContact({...editingContact, address: e.target.value})}
                  data-testid="input-address"
                />
              </div>
              <div>
                <Label htmlFor="notes">Notes</Label>
                <Textarea
                  id="notes"
                  value={editingContact.notes || ''}
                  onChange={(e) => setEditingContact({...editingContact, notes: e.target.value})}
                  data-testid="input-notes"
                />
              </div>
            </div>
            <div className="flex justify-end space-x-2 pt-4">
              <Button variant="outline" onClick={() => setEditingContact(null)} data-testid="cancel-edit">
                Cancel
              </Button>
              <Button 
                onClick={() => {
                  if (editingContact.id) {
                    updateContactMutation.mutate(editingContact);
                  } else {
                    // For new contacts, we need an API endpoint to create them
                    console.log("Creating new contact:", editingContact);
                    setEditingContact(null);
                    toast({
                      title: "Contact Created",
                      description: "New contact has been added.",
                    });
                  }
                }}
                disabled={updateContactMutation.isPending}
                data-testid="save-contact"
              >
                {updateContactMutation.isPending ? 'Saving...' : 'Save'}
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      )}

      {/* Delete Confirmation Dialog */}
      {deletingContact && (
        <Dialog open={!!deletingContact} onOpenChange={() => setDeletingContact(null)}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Delete Contact</DialogTitle>
            </DialogHeader>
            <p>Are you sure you want to delete {[deletingContact.firstName, deletingContact.lastName].filter(Boolean).join(' ')}? This action cannot be undone.</p>
            <div className="flex justify-end space-x-2 pt-4">
              <Button variant="outline" onClick={() => setDeletingContact(null)} data-testid="cancel-delete">
                Cancel
              </Button>
              <Button 
                variant="destructive"
                onClick={() => deleteContactMutation.mutate(deletingContact.id)}
                disabled={deleteContactMutation.isPending}
                data-testid="confirm-delete"
              >
                {deleteContactMutation.isPending ? 'Deleting...' : 'Delete'}
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}

client/src/components/lists/shopping-lis.content:
import React, { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Plus, Mic, Trash2, Apple, Milk, Wheat, Share2, Copy, MessageCircle, UserPlus, Mail } from "lucide-react";
import { api } from "@/lib/api";
import { useVoice } from "@/hooks/use-voice";
import { useToast } from "@/hooks/use-toast";
import { Skeleton } from "@/components/ui/skeleton";
import type { User, SmartList, ListItem } from "@shared/schema";

interface ShoppingListsProps {
  user: User;
}

const categoryIcons = {
  produce: Apple,
  dairy: Milk,
  grains: Wheat,
};

const getCategoryIcon = (category: string) => {
  const Icon = categoryIcons[category.toLowerCase() as keyof typeof categoryIcons];
  return Icon || Apple;
};

const getCategoryColor = (category: string) => {
  const colors = {
    produce: "text-green-500",
    dairy: "text-yellow-500",
    grains: "text-amber-500",
    meat: "text-red-500",
    pantry: "text-blue-500",
  };
  return colors[category.toLowerCase() as keyof typeof colors] || "text-gray-500";
};

export function ShoppingLists({ user }: ShoppingListsProps) {
  const [newListName, setNewListName] = useState("");
  const [newItemName, setNewItemName] = useState("");
  const [newItemCategory, setNewItemCategory] = useState("");
  const [selectedListId, setSelectedListId] = useState<string | null>(null);
  const [isVoiceAddingItem, setIsVoiceAddingItem] = useState(false);
  const [shareDialogOpen, setShareDialogOpen] = useState(false);
  const [selectedListForShare, setSelectedListForShare] = useState<SmartList | null>(null);
  const [collaboratorEmail, setCollaboratorEmail] = useState("");
  const [searchingUser, setSearchingUser] = useState(false);
  const [foundUser, setFoundUser] = useState<{id: string, email: string, firstName?: string, lastName?: string} | null>(null);
  const [editingListId, setEditingListId] = useState<string | null>(null);
  const [editingListName, setEditingListName] = useState("");
  const [isGeneratingName, setIsGeneratingName] = useState(false);

  const queryClient = useQueryClient();
  const { toast } = useToast();

  // Get shopping lists
  const { data: lists = [], isLoading } = useQuery<(SmartList & { items: ListItem[] })[]>({
    queryKey: ["/api/smart-lists", user.id],
  });

  // Create list mutation
  const createListMutation = useMutation({
    mutationFn: (name: string) => api.createSmartList({
      userId: user.id,
      name,
      type: "shopping",
      categories: ["Produce", "Dairy", "Meat", "Pantry", "Frozen", "Beverages", "Household"]
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      setNewListName("");
      toast({
        title: "List Created",
        description: "Your new shopping list has been created.",
      });
    },
  });

  // Create item mutation
  const createItemMutation = useMutation({
    mutationFn: ({ listId, name, category }: { listId: string; name: string; category?: string }) =>
      api.createListItem({ listId, name, category }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      setNewItemName("");
      setNewItemCategory("");
      toast({
        title: "Item Added",
        description: "Item has been added to your list.",
      });
    },
    onError: (error: any) => {
      console.error("Create item error:", error);
      toast({
        title: "Error Adding Item",
        description: error.message || "Failed to add item to list",
        variant: "destructive",
      });
    },
  });

  // Update item mutation
  const updateItemMutation = useMutation({
    mutationFn: ({ id, updates }: { id: string; updates: Partial<ListItem> }) =>
      api.updateListItem(id, updates),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
    },
  });

  // Delete item mutation
  const deleteItemMutation = useMutation({
    mutationFn: (id: string) => api.deleteListItem(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      toast({
        title: "Item Removed",
        description: "Item has been removed from your list.",
      });
    },
  });

  // Share list mutation
  const shareListMutation = useMutation({
    mutationFn: (listId: string) => api.shareList(listId),
    onSuccess: (shareCode) => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      toast({
        title: "List Shared!",
        description: "Your list is now shareable via the link below.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Sharing Failed",
        description: error.message || "Failed to share list",
        variant: "destructive",
      });
    },
  });

  // Add collaborator mutation
  const addCollaboratorMutation = useMutation({
    mutationFn: ({ listId, email }: { listId: string; email: string }) => 
      api.addCollaborator(listId, email),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      setCollaboratorEmail("");
      setFoundUser(null);
      toast({
        title: "Collaborator Added!",
        description: "User has been invited to collaborate on your list.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Failed to Add Collaborator",
        description: error.message || "Could not add collaborator to the list.",
        variant: "destructive",
      });
    },
  });

  // Update list mutation
  const updateListMutation = useMutation({
    mutationFn: ({ id, updates }: { id: string; updates: Partial<SmartList> }) => 
      api.updateSmartList(id, updates),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      setEditingListId(null);
      setEditingListName("");
      toast({
        title: "List Updated",
        description: "List name has been updated successfully.",
      });
    },
  });

  // Voice input for adding items
  const { isRecording, isTranscribing, toggleRecording, stopRecording } = useVoice({
    onTranscriptionComplete: (text) => {
      console.log("Voice transcription complete:", text);
      if (isVoiceAddingItem && selectedListId && text.trim()) {
        const category = categorizeItem(text, user);
        createItemMutation.mutate({
          listId: selectedListId,
          name: text.trim(),
          category,
        });
        toast({
          title: "Item Added",
          description: `Added "${text}" to your list`,
        });
      }
      setNewItemName("");
      setIsVoiceAddingItem(false);
      setSelectedListId(null);
    },
    onError: (error) => {
      setIsVoiceAddingItem(false);
      setSelectedListId(null);
      console.error("Voice input error:", error);
      toast({
        title: "Voice Error",
        description: "Failed to record voice input. Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleCreateList = () => {
    if (newListName.trim()) {
      createListMutation.mutate(newListName.trim());
    }
  };

  const handleAddItem = (listId: string) => {
    if (newItemName.trim()) {
      // Smart categorization based on user preferences
      const category = categorizeItem(newItemName, user);
      createItemMutation.mutate({
        listId,
        name: newItemName.trim(),
        category: newItemCategory || category,
      });
    }
  };

  const handleToggleItem = (item: ListItem) => {
    updateItemMutation.mutate({
      id: item.id,
      updates: { completed: !item.completed },
    });
  };

  const handleDeleteItem = (id: string) => {
    deleteItemMutation.mutate(id);
  };

  const handleEditListName = (list: SmartList & { items: ListItem[] }) => {
    setEditingListId(list.id);
    setEditingListName(list.name);
  };

  const handleSaveListName = () => {
    if (editingListId && editingListName.trim()) {
      updateListMutation.mutate({
        id: editingListId,
        updates: { name: editingListName.trim() }
      });
    }
  };

  const handleCancelEdit = () => {
    setEditingListId(null);
    setEditingListName("");
  };

  const generateSmartListName = async () => {
    setIsGeneratingName(true);
    try {
      const response = await api.generateListName(user);
      setNewListName(response.name);
      toast({
        title: "Smart Name Generated",
        description: `Suggested: "${response.name}"`,
      });
    } catch (error) {
      console.error("Failed to generate list name:", error);
      toast({
        title: "Name Generation Failed",
        description: "Using default name instead",
        variant: "destructive",
      });
    } finally {
      setIsGeneratingName(false);
    }
  };

  const handleVoiceAddItem = async (listId: string) => {
    try {
      // Force stop any existing recording with cleanup
      if (isRecording || isTranscribing) {
        stopRecording();
        // Wait for cleanup to complete
        await new Promise(resolve => setTimeout(resolve, 200));
      }

      setSelectedListId(listId);
      setIsVoiceAddingItem(true);

      // Start new recording
      toggleRecording();
    } catch (error) {
      console.error("Voice input error:", error);
      setIsVoiceAddingItem(false);
    }
  };

  const handleShareList = (list: SmartList & { items: ListItem[] }) => {
    setSelectedListForShare(list);
    setShareDialogOpen(true);
    if (!list.shareCode) {
      shareListMutation.mutate(list.id);
    }
  };

  const getShareUrl = (shareCode: string) => {
    return `${window.location.origin}/shared/${shareCode}`;
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast({
      title: "Copied!",
      description: "Share link copied to clipboard.",
    });
  };

  const shareViaWhatsApp = (shareCode: string, listName: string) => {
    const url = getShareUrl(shareCode);
    const message = `Hey! I'm sharing my "${listName}" list with you via GabAi. You can view and collaborate here: ${url}`;
    const whatsappUrl = `https://wa.me/?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const shareViaSMS = (shareCode: string, listName: string) => {
    const url = getShareUrl(shareCode);
    const message = `Hey! I'm sharing my "${listName}" list with you via GabAi: ${url}`;
    const smsUrl = `sms:?body=${encodeURIComponent(message)}`;
    window.open(smsUrl);
  };

  const searchUser = async () => {
    if (!collaboratorEmail.trim()) return;

    setSearchingUser(true);
    setFoundUser(null);

    try {
      const user = await api.searchUserByEmail(collaboratorEmail.trim());
      setFoundUser(user);
    } catch (error: any) {
      if (error.message.includes('404')) {
        toast({
          title: "User Not Found",
          description: "No registered user found with this email address.",
          variant: "destructive",
        });
      } else {
        toast({
          title: "Search Failed",
          description: "Failed to search for user.",
          variant: "destructive",
        });
      }
    } finally {
      setSearchingUser(false);
    }
  };

  const handleAddCollaborator = () => {
    if (foundUser && selectedListForShare) {
      addCollaboratorMutation.mutate({
        listId: selectedListForShare.id,
        email: foundUser.email,
      });
    }
  };

  // Group items by category
  const groupItemsByCategory = (items: ListItem[]) => {
    const grouped = items.reduce((acc, item) => {
      const category = item.category || "Other";
      if (!acc[category]) acc[category] = [];
      acc[category].push(item);
      return acc;
    }, {} as Record<string, ListItem[]>);

    return grouped;
  };

  if (isLoading) {
    return (
      <div className="p-4 space-y-4">
        {[1, 2, 3].map((i) => (
          <Skeleton key={i} className="h-32 w-full" />
        ))}
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="p-4 bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
            Shopping Lists
          </h2>
          <Dialog>
            <DialogTrigger asChild>
              <Button size="sm" className="w-10 h-10 rounded-full p-0">
                <Plus className="h-5 w-5" />
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Create New List</DialogTitle>
              </DialogHeader>
              <div className="space-y-4">
                <div>
                  <div className="flex items-center justify-between">
                    <Label htmlFor="list-name">List Name</Label>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={generateSmartListName}
                      disabled={isGeneratingName}
                      className="text-xs h-6 px-2"
                    >
                      {isGeneratingName ? "Generating..." : "🧠 Smart Name"}
                    </Button>
                  </div>
                  <Input
                    id="list-name"
                    value={newListName}
                    onChange={(e) => setNewListName(e.target.value)}
                    placeholder="e.g., Parkview Apartments"
                    dir="auto"
                    style={{ unicodeBidi: 'plaintext', textAlign: 'start' }}
                    className="mt-1"
                  />
                  {isGeneratingName && (
                    <p className="text-xs text-blue-600 mt-1">
                      GabAi is analyzing your activity to suggest a smart list name...
                    </p>
                  )}
                </div>
                <Button 
                  onClick={handleCreateList}
                  disabled={!newListName.trim() || createListMutation.isPending}
                  className="w-full"
                >
                  Create List
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </div>
      </div>

      {/* Lists */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {lists.length === 0 ? (
          <div className="text-center py-8">
            <p className="text-gray-500 dark:text-gray-400 mb-4">
              No shopping lists yet. Create your first list!
            </p>
          </div>
        ) : (
          lists.map((list: SmartList & { items: ListItem[] }) => (
            <ShoppingListCard
              key={list.id}
              list={list}
              user={user}
              onAddItem={handleAddItem}
              onToggleItem={handleToggleItem}
              onDeleteItem={handleDeleteItem}
              onVoiceAdd={handleVoiceAddItem}
              onShare={() => handleShareList(list)}
              onEditName={() => handleEditListName(list)}
              newItemName={selectedListId === list.id ? newItemName : ""}
              setNewItemName={setNewItemName}
              newItemCategory={newItemCategory}
              setNewItemCategory={setNewItemCategory}
              isVoiceMode={isVoiceAddingItem && selectedListId === list.id}
              isRecording={isRecording}
              isTranscribing={isTranscribing}
              editingListId={editingListId}
              editingListName={editingListName}
              setEditingListName={setEditingListName}
              onSaveListName={handleSaveListName}
              onCancelEdit={handleCancelEdit}
            />
          ))
        )}
      </div>

      {/* Share Dialog */}
      <Dialog open={shareDialogOpen} onOpenChange={setShareDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Share "{selectedListForShare?.name}"</DialogTitle>
          </DialogHeader>
          <div className="space-y-6">
            {/* Invite App Users */}
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <UserPlus className="h-4 w-4" />
                <label className="text-sm font-medium">Invite App Users</label>
              </div>
              <div className="space-y-3">
                <div className="flex items-center space-x-2">
                  <Input
                    value={collaboratorEmail}
                    onChange={(e) => {
                      setCollaboratorEmail(e.target.value);
                      setFoundUser(null);
                    }}
                    placeholder="Enter email address"
                    className="flex-1"
                    onKeyPress={(e) => {
                      if (e.key === "Enter") {
                        searchUser();
                      }
                    }}
                  />
                  <Button
                    size="sm"
                    onClick={searchUser}
                    disabled={!collaboratorEmail.trim() || searchingUser}
                    variant="outline"
                  >
                    {searchingUser ? "..." : "Search"}
                  </Button>
                </div>

                {foundUser && (
                  <div className="flex items-center justify-between p-3 bg-green-50 dark:bg-green-900/20 rounded-lg border border-green-200 dark:border-green-800">
                    <div className="flex items-center gap-3">
                      <UserPlus className="h-4 w-4 text-green-600" />
                      <div>
                        <p className="text-sm font-medium text-green-900 dark:text-green-100">
                          {foundUser.firstName && foundUser.lastName 
                            ? `${foundUser.firstName} ${foundUser.lastName}`
                            : foundUser.email
                          }
                        </p>
                        <p className="text-xs text-green-600 dark:text-green-400">
                          {foundUser.email}
                        </p>
                      </div>
                    </div>
                    <Button
                      size="sm"
                      onClick={handleAddCollaborator}
                      disabled={addCollaboratorMutation.isPending}
                      className="bg-green-600 hover:bg-green-700 text-white"
                    >
                      {addCollaboratorMutation.isPending ? "Adding..." : "Add"}
                    </Button>
                  </div>
                )}
              </div>
              <p className="text-xs text-gray-500 dark:text-gray-400">
                Registered users will get instant access to collaborate
              </p>
            </div>

            {/* Show collaborators */}
            {selectedListForShare?.collaborators && selectedListForShare.collaborators.length > 0 && (
              <div className="space-y-2">
                <label className="text-sm font-medium">Current Collaborators</label>
                <div className="space-y-1">
                  {selectedListForShare.collaborators.map((collaboratorId, index) => (
                    <div key={index} className="text-sm text-gray-600 dark:text-gray-400 flex items-center gap-2">
                      <UserPlus className="h-3 w-3" />
                      {collaboratorId}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Public Link Sharing */}
            {selectedListForShare?.shareCode && (
              <>
                <hr className="border-gray-200 dark:border-gray-700" />
                <div className="space-y-3">
                  <div className="flex items-center gap-2">
                    <Share2 className="h-4 w-4" />
                    <label className="text-sm font-medium">Public Link</label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Input
                      value={getShareUrl(selectedListForShare.shareCode)}
                      readOnly
                      className="flex-1"
                    />
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => selectedListForShare.shareCode && copyToClipboard(getShareUrl(selectedListForShare.shareCode))}
                    >
                      <Copy className="h-4 w-4" />
                    </Button>
                  </div>

                  <div className="flex flex-col gap-2">
                    <Button
                      onClick={() => selectedListForShare.shareCode && shareViaWhatsApp(selectedListForShare.shareCode, selectedListForShare.name)}
                      className="w-full"
                      variant="outline"
                    >
                      <MessageCircle className="h-4 w-4 mr-2" />
                      Share via WhatsApp
                    </Button>
                    <Button
                      onClick={() => selectedListForShare.shareCode && shareViaSMS(selectedListForShare.shareCode, selectedListForShare.name)}
                      className="w-full"
                      variant="outline"
                    >
                      <MessageCircle className="h-4 w-4 mr-2" />
                      Share via Text Message
                    </Button>
                  </div>

                  <div className="text-xs text-gray-500 dark:text-gray-400">
                    Anyone with this link can view and add items (no account required)
                  </div>
                </div>
              </>
            )}

            {shareListMutation.isPending && (
              <div className="text-center py-4">
                <div className="text-sm text-gray-600 dark:text-gray-400">
                  Generating share link...
                </div>
              </div>
            )}
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

interface ShoppingListCardProps {
  list: SmartList & { items: ListItem[] };
  user: User;
  onAddItem: (listId: string) => void;
  onToggleItem: (item: ListItem) => void;
  onDeleteItem: (id: string) => void;
  onVoiceAdd: (listId: string) => void;
  onShare: () => void;
  onEditName: () => void;
  newItemName: string;
  setNewItemName: (name: string) => void;
  newItemCategory: string;
  setNewItemCategory: (category: string) => void;
  isVoiceMode: boolean;
  isRecording: boolean;
  isTranscribing: boolean;
  editingListId: string | null;
  editingListName: string;
  setEditingListName: (name: string) => void;
  onSaveListName: () => void;
  onCancelEdit: () => void;
}

function ShoppingListCard({
  list,
  user,
  onAddItem,
  onToggleItem,
  onDeleteItem,
  onVoiceAdd,
  onShare,
  onEditName,
  newItemName,
  setNewItemName,
  newItemCategory,
  setNewItemCategory,
  isVoiceMode,
  isRecording,
  isTranscribing,
  editingListId,
  editingListName,
  setEditingListName,
  onSaveListName,
  onCancelEdit,
}: ShoppingListCardProps) {
  const groupedItems = groupItemsByCategory(list.items);
  const completedCount = list.items.filter(item => item.completed).length;

  return (
    <Card>
      <CardHeader className="pb-4">
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="text-lg flex items-center gap-2">
              {editingListId === list.id ? (
                <div className="flex items-center gap-2 flex-1">
                  <Input
                    value={editingListName}
                    onChange={(e) => setEditingListName(e.target.value)}
                    dir="auto"
                    style={{ unicodeBidi: 'plaintext', textAlign: 'start' }}
                    className="text-lg font-semibold"
                    onKeyPress={(e) => {
                      if (e.key === "Enter") {
                        onSaveListName();
                      } else if (e.key === "Escape") {
                        onCancelEdit();
                      }
                    }}
                    autoFocus
                  />
                  <Button size="sm" onClick={onSaveListName} disabled={!editingListName.trim()}>
                    Save
                  </Button>
                  <Button size="sm" variant="outline" onClick={onCancelEdit}>
                    Cancel
                  </Button>
                </div>
              ) : (
                <div className="flex items-center gap-2">
                  <span onClick={onEditName} className="cursor-pointer hover:text-blue-600">{list.name}</span>
                  {list.userId !== user.id && (
                    <span className="text-xs bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300 px-2 py-1 rounded-full">
                      Shared with me
                    </span>
                  )}
                </div>
              )}
            </CardTitle>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              {completedCount} of {list.items.length} completed
              {list.isShared && (
                <span className="ml-2 text-blue-500">• Public</span>
              )}
              {list.collaborators && list.collaborators.length > 0 && (
                <span className="ml-2 text-green-500">• {list.collaborators.length} collaborator{list.collaborators.length === 1 ? '' : 's'}</span>
              )}
            </p>
          </div>
          <Button
            size="sm"
            variant="outline"
            onClick={onShare}
            className="w-10 h-10 p-0"
          >
            <Share2 className="h-4 w-4" />
          </Button>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Add new item */}
        <div className="flex items-center space-x-2">
          <Button
            size="sm"
            variant="outline"
            onClick={() => onVoiceAdd(list.id)}
            disabled={isRecording || isTranscribing}
            className="w-10 h-10 p-0"
          >
            <Mic className={`h-4 w-4 ${isRecording ? "text-red-500" : ""}`} />
          </Button>
          <div className="flex-1">
            <Input
              value={newItemName}
              onChange={(e) => setNewItemName(e.target.value)}
              placeholder="Add item to list..."
              dir="auto"
              style={{ unicodeBidi: 'plaintext', textAlign: 'start' }}
              onKeyPress={(e) => {
                if (e.key === "Enter") {
                  onAddItem(list.id);
                }
              }}
            />
          </div>
          <Button
            size="sm"
            onClick={() => onAddItem(list.id)}
            disabled={!newItemName.trim()}
          >
            Add
          </Button>
        </div>

        {isVoiceMode && (isRecording || isTranscribing) && (
          <div className="flex items-center justify-center space-x-2 py-2">
            {isRecording && (
              <>
                <div className="w-3 h-3 bg-red-500 rounded-full animate-pulse"></div>
                <span className="text-sm text-gray-600 dark:text-gray-400">Recording...</span>
              </>
            )}
            {isTranscribing && (
              <>
                <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                <span className="text-sm text-gray-600 dark:text-gray-400">Processing...</span>
              </>
            )}
          </div>
        )}

        {/* Items grouped by category */}
        {Object.entries(groupedItems).map(([category, items]) => (
          <div key={category} className="space-y-2">
            <div className="flex items-center space-x-2">
              {React.createElement(getCategoryIcon(category), {
                className: `h-4 w-4 ${getCategoryColor(category)}`,
              })}
              <h4 className="text-sm font-medium text-gray-700 dark:text-gray-300">
                {category}
                {category.toLowerCase().includes("dairy") && 
                 user.preferences?.dietary?.includes("Dairy-free") && (
                  <span className="ml-2 text-xs bg-blue-100 dark:bg-blue-900 text-blue-800 dark:text-blue-200 px-2 py-1 rounded">
                    Dairy-free options
                  </span>
                )}
              </h4>
            </div>

            <div className="space-y-1 ml-6">
              {items.map((item) => (
                <div key={item.id} className="flex items-center space-x-3 group">
                  <Checkbox
                    checked={item.completed || false}
                    onCheckedChange={() => onToggleItem(item)}
                  />
                  <span 
                    className={`flex-1 text-sm ${
                      item.completed 
                        ? "line-through text-gray-500 dark:text-gray-400" 
                        : "text-gray-900 dark:text-white"
                    }`}
                  >
                    {item.name}
                  </span>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => onDeleteItem(item.id)}
                    className="opacity-0 group-hover:opacity-100 w-6 h-6 p-0"
                  >
                    <Trash2 className="h-3 w-3" />
                  </Button>
                </div>
              ))}
            </div>
          </div>
        ))}

        {list.items.length === 0 && (
          <p className="text-center text-gray-500 dark:text-gray-400 py-4">
            No items in this list yet.
          </p>
        )}
      </CardContent>
    </Card>
  );
}

// Smart categorization function
function categorizeItem(itemName: string, user: User): string {
  const name = itemName.toLowerCase();

  // Produce
  if (name.match(/\b(apple|banana|orange|lettuce|spinach|carrot|tomato|potato|onion|garlic|pepper|cucumber|broccoli|avocado)\b/)) {
    return "Produce";
  }

  // Dairy (consider user preferences)
  if (name.match(/\b(milk|cheese|yogurt|butter|cream)\b/)) {
    if (user.preferences?.dietary?.includes("Dairy-free")) {
      return "Dairy Alternatives";
    }
    return "Dairy";
  }

  // Meat
  if (name.match(/\b(chicken|beef|pork|fish|salmon|turkey|ham|bacon)\b/)) {
    return "Meat";
  }

  // Grains
  if (name.match(/\b(bread|rice|pasta|cereal|oats|quinoa|flour)\b/)) {
    return "Grains";
  }

  return "Other";
}

function groupItemsByCategory(items: ListItem[]): Record<string, ListItem[]> {
  const grouped = items.reduce((acc, item) => {
    const category = item.category || "Other";
    if (!acc[category]) acc[category] = [];
    acc[category].push(item);
    return acc;
  }, {} as Record<string, ListItem[]>);

  return grouped;
}

