        style={{ touchAction: 'none' }}
        onTouchStart={(e) => {
          // Prevent body scroll during drag
          document.body.style.overflow = 'hidden';
        }}
        onTouchEnd={(e) => {
          // Restore body scroll after drag
          document.body.style.overflow = '';
        }}
        onMouseDown={(e) => {
          // Prevent text selection during drag
          e.preventDefault();
        }}
