import { useEffect } from 'react';
import { isNativeApp } from '@/utils/capacitor';

export function useCapacitorDetection() {
  useEffect(() => {
    // Add Capacitor-specific CSS class to body
    if (isNativeApp()) {
      document.body.classList.add('capacitor-native');

      // Add viewport meta for mobile apps
      const viewport = document.querySelector('meta[name=viewport]');
      if (viewport) {
        viewport.setAttribute('content', 
          'width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover'
        );
      }

      // Prevent pull-to-refresh and other mobile gestures
      document.body.style.overscrollBehavior = 'none';
      document.body.style.touchAction = 'pan-x pan-y';
    }
  }, []);
}

import { useCallback } from 'react';

// Capacitor native scheduling system for alarms, reminders, and recurring events
// Provides better mobile UX than web-based date pickers

declare global {
  interface Window {
    Capacitor?: {
      isNativePlatform(): boolean;
    };
  }
}

interface ScheduleOptions {
  title: string;
  description?: string;
  date: Date;
  recurring?: 'none' | 'daily' | 'weekly' | 'monthly' | 'yearly';
  sound?: string;
  vibration?: boolean;
  voiceOptions?: {
    text: string;
    personality: 'drill-sergeant' | 'gentle' | 'funny';
  };
}

interface DatePickerOptions {
  mode: 'date' | 'time' | 'datetime';
  format?: string;
  theme?: 'light' | 'dark';
  min?: Date;
  max?: Date;
}

export function useCapacitorScheduler() {
  // Native date/time picker
  const showDatePicker = useCallback(async (options: DatePickerOptions): Promise<Date | null> => {
    try {
      if (window.Capacitor?.isNativePlatform()) {
        // Use Capacitor native date picker - dynamically imported
        // const { DatetimePicker } = await import('@capacitor-community/datetime-picker');

        // Fallback to web picker for now (Capacitor datetime picker will be configured separately)
        return showWebDatePicker(options);
      } else {
        return showWebDatePicker(options);
      }
    } catch (error) {
      console.error('Date picker error:', error);
      return null;
    }
  }, []);

  // Schedule native alarm/notification
  const scheduleAlarm = useCallback(async (options: ScheduleOptions): Promise<number | null> => {
    console.log('🔔 APK scheduleAlarm called with:', options);
    console.log('🔔 APK Current time:', new Date());
    console.log('🔔 APK Scheduled time:', options.date);
    console.log('🔔 APK Time difference (ms):', options.date.getTime() - Date.now());

    try {
      if (window.Capacitor?.isNativePlatform()) {
        console.log('📱 APK Using native Capacitor platform');

        try {
          const { LocalNotifications } = await import('@capacitor/local-notifications');

          // Request permissions first
          console.log('🔔 APK Requesting notification permissions...');
          const permission = await LocalNotifications.requestPermissions();
          console.log('🔔 APK Permission result:', permission);

          if (permission.display !== 'granted') {
            throw new Error('Notification permissions not granted. Please enable notifications in your device settings.');
          }

          const notificationId = Date.now();
          console.log('🔔 APK Generated notification ID:', notificationId);

          // Schedule the notification
          console.log('🔔 APK Scheduling notification...');
          await LocalNotifications.schedule({
            notifications: [{
              id: notificationId,
              title: options.title,
              body: options.description || '',
              schedule: {
                at: options.date,
                repeats: options.recurring !== 'none',
                every: getRepeatInterval(options.recurring)
              },
              sound: options.sound || 'default',
              actionTypeId: 'ALARM_ACTION',
            }]
          });

          console.log('✅ APK Notification scheduled successfully');
          return notificationId;
        } catch (importError) {
          console.error('🔔 APK LocalNotifications import failed:', importError);
          throw new Error('Alarm system not available in this APK version');
        }

        return notificationId;
      } else {
        console.log('🌐 Using web fallback platform');
        // Web fallback using setTimeout and browser notifications
        const timeUntilAlarm = options.date.getTime() - Date.now();
        console.log('⏰ Time until alarm (ms):', timeUntilAlarm);

        if (timeUntilAlarm > 0) {
          const alarmId = Date.now();

          // Request notification permission first
          let permissionGranted = false;
          if ('Notification' in window) {
            const permission = await Notification.requestPermission();
            permissionGranted = permission === 'granted';
            console.log('🔔 Notification permission:', permission);
          }

          // Store alarm in localStorage for retrieval
          const webAlarms = JSON.parse(localStorage.getItem('gabai-web-alarms') || '[]');
          webAlarms.push({
            id: alarmId,
            title: options.title,
            body: options.description,
            schedule: { at: options.date },
            timeoutId: null
          });
          localStorage.setItem('gabai-web-alarms', JSON.stringify(webAlarms));
          console.log('💾 Alarm stored in localStorage:', webAlarms);

          const timeoutId = setTimeout(async () => {
            console.log('⏰ Alarm triggered!', options.title);
            if (permissionGranted) {
              new Notification(options.title, {
                body: options.description,
                icon: '/icon-192x192.png',
                requireInteraction: true,
                tag: `gabai-alarm-${alarmId}`
              });
            } else {
              // Fallback alert if notifications not supported
              alert(`🔔 Alarm: ${options.title}\n${options.description || ''}`);
            }

            // Play sound if available
            if (options.sound && options.sound !== 'default') {
              const audio = new Audio(options.sound);
              audio.play().catch(console.error);
            }

            // Remove from localStorage after triggering
            const updatedAlarms = JSON.parse(localStorage.getItem('gabai-web-alarms') || '[]')
              .filter((alarm: any) => alarm.id !== alarmId);
            localStorage.setItem('gabai-web-alarms', JSON.stringify(updatedAlarms));
          }, timeUntilAlarm);

          console.log('✅ Alarm scheduled with ID:', alarmId);
          return alarmId;
        } else {
          console.log('❌ Time until alarm is negative or zero, cannot schedule');
          return null;
        }
      }
    } catch (error) {
      console.error('❌ Alarm scheduling error:', error);
      return null;
    }
  }, []);

  // Cancel scheduled alarm
  const cancelAlarm = useCallback(async (alarmId: number): Promise<boolean> => {
    try {
      if (window.Capacitor?.isNativePlatform()) {
        const { LocalNotifications } = await import('@capacitor/local-notifications');
        await LocalNotifications.cancel({ notifications: [{ id: alarmId }] });
        return true;
      } else {
        // Web fallback - limited cancellation support
        console.log(`Cancelling alarm ${alarmId} (web fallback)`);
        return true;
      }
    } catch (error) {
      console.error('Alarm cancellation error:', error);
      return false;
    }
  }, []);

  // Get all scheduled alarms
  const getScheduledAlarms = useCallback(async () => {
    try {
      if (window.Capacitor?.isNativePlatform()) {
        const { LocalNotifications } = await import('@capacitor/local-notifications');
        const result = await LocalNotifications.getPending();
        return result.notifications.map(n => ({
          id: n.id,
          title: n.title,
          body: n.body,
          schedule: n.schedule
        }));
      } else {
        // Web fallback - check localStorage for web alarms
        const webAlarms = localStorage.getItem('gabai-web-alarms');
        if (webAlarms) {
          const alarms = JSON.parse(webAlarms);
          // Filter out expired alarms
          const activeAlarms = alarms.filter((alarm: any) => new Date(alarm.schedule.at) > new Date());
          localStorage.setItem('gabai-web-alarms', JSON.stringify(activeAlarms));
          return activeAlarms;
        }
        return [];
      }
    } catch (error) {
      console.error('Get alarms error:', error);
      return [];
    }
  }, []);

  return {
    showDatePicker,
    scheduleAlarm,
    cancelAlarm,
    getScheduledAlarms
  };
}

// Helper functions
function formatDateForInput(date: Date, mode: string): string {
  if (mode === 'time') {
    return date.toTimeString().slice(0, 5);
  } else if (mode === 'datetime') {
    return date.toISOString().slice(0, 16);
  } else {
    return date.toISOString().slice(0, 10);
  }
}

function showWebDatePicker(options: DatePickerOptions): Promise<Date | null> {
  return new Promise((resolve) => {
    const input = document.createElement('input');
    input.type = options.mode === 'time' ? 'time' : 
               options.mode === 'datetime' ? 'datetime-local' : 'date';

    if (options.min) input.min = formatDateForInput(options.min, options.mode);
    if (options.max) input.max = formatDateForInput(options.max, options.mode);

    input.style.position = 'fixed';
    input.style.top = '-9999px';
    document.body.appendChild(input);

    input.addEventListener('change', () => {
      const selectedDate = input.value ? new Date(input.value) : null;
      document.body.removeChild(input);
      resolve(selectedDate);
    });

    input.addEventListener('blur', () => {
      setTimeout(() => {
        if (input.parentNode) {
          document.body.removeChild(input);
          resolve(null);
        }
      }, 100);
    });

    input.focus();
    input.click();
  });
}

function getRepeatInterval(recurring?: string) {
  switch (recurring) {
    case 'daily': return 'day';
    case 'weekly': return 'week';
    case 'monthly': return 'month';
    case 'yearly': return 'year';
    default: return undefined;
  }
}

import { useCallback } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useToast } from '@/hooks/use-toast';

interface GabAiListAction {
  action: 'add' | 'remove' | 'create_list' | 'move_item';
  listName?: string;
  listType?: 'shopping' | 'todo' | 'punch-list';
  itemText?: string;
  itemId?: string;
  category?: string;
}

export function useEnhancedGabAi() {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Create new list mutation
  const createListMutation = useMutation({
    mutationFn: async (data: { name: string; type: 'shopping' | 'todo' | 'punch-list' }) => {
      const response = await fetch('/api/smart-lists', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
      });
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/lists"] });
    }
  });

  // Add item mutation
  const addItemMutation = useMutation({
    mutationFn: async (data: { listId: string; text: string; category?: string }) => {
      const response = await fetch(`/api/smart-lists/${data.listId}/items`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: data.text,
          category: data.category || 'general',
          priority: 1,
          completed: false,
          quantity: 1
        })
      });
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/lists"] });
    }
  });

  // Remove item mutation
  const removeItemMutation = useMutation({
    mutationFn: async (itemId: string) => {
      const response = await fetch(`/api/smart-lists/items/${itemId}`, {
        method: 'DELETE'
      });
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/lists"] });
    }
  });

  const analyzeUserRequest = useCallback((input: string, existingLists: any[]): GabAiListAction => {
    const lowerInput = input.toLowerCase();

    // Remove/delete patterns
    const removePatterns = [
      'remove', 'delete', 'take off', 'cross out', 'done with', 
      'finished', 'completed', 'got it', 'bought', 'no longer need'
    ];

    // Add patterns
    const addPatterns = [
      'add', 'put', 'include', 'need', 'buy', 'get', 'pick up',
      'remember to', 'don\'t forget', 'also need'
    ];

    // List type detection
    const shoppingWords = ['buy', 'grocery', 'store', 'market', 'food', 'milk', 'bread', 'eggs'];
    const todoWords = ['task', 'do', 'call', 'email', 'meeting', 'appointment', 'work'];
    const punchWords = ['fix', 'repair', 'broken', 'maintenance', 'install', 'clean'];

    // Check for remove action
    if (removePatterns.some(pattern => lowerInput.includes(pattern))) {
      // Try to find item to remove by matching text
      const itemText = lowerInput.replace(/(remove|delete|take off|cross out|done with|finished|completed|got it|bought|no longer need)\s+/gi, '').trim();

      return {
        action: 'remove',
        itemText: itemText
      };
    }

    // Check for add action or implicit add
    const isExplicitAdd = addPatterns.some(pattern => lowerInput.includes(pattern));

    // Determine list type based on content
    const shoppingScore = shoppingWords.filter(word => lowerInput.includes(word)).length;
    const todoScore = todoWords.filter(word => lowerInput.includes(word)).length;
    const punchScore = punchWords.filter(word => lowerInput.includes(word)).length;

    let suggestedType: 'shopping' | 'todo' | 'punch-list' = 'shopping'; // default

    if (punchScore > shoppingScore && punchScore > todoScore) {
      suggestedType = 'punch-list';
    } else if (todoScore > shoppingScore) {
      suggestedType = 'todo';
    }

    // Find existing list of the right type
    const existingList = existingLists.find(list => list.type === suggestedType);

    // Extract item text (remove command words)
    let itemText = input;
    addPatterns.forEach(pattern => {
      itemText = itemText.replace(new RegExp(`\\b${pattern}\\s+`, 'gi'), '');
    });
    itemText = itemText.trim();

    // If no existing list, suggest creating one
    if (!existingList) {
      const listNames = {
        'shopping': 'Groceries & Errands',
        'todo': 'Tasks & Reminders', 
        'punch-list': 'Home Repairs'
      };

      return {
        action: 'create_list',
        listName: listNames[suggestedType],
        listType: suggestedType,
        itemText: itemText
      };
    }

    // Add to existing list
    return {
      action: 'add',
      listName: existingList.name,
      listType: suggestedType,
      itemText: itemText,
      category: suggestedType === 'shopping' ? 'grocery' : 'general'
    };
  }, []);

  const executeGabAiAction = useCallback(async (
    action: GabAiListAction, 
    existingLists: any[],
    allItems: any[]
  ) => {
    try {
      switch (action.action) {
        case 'remove':
          // Find item by text match
          const itemToRemove = allItems.find(item => 
            item.text.toLowerCase().includes(action.itemText?.toLowerCase() || '')
          );

          if (itemToRemove) {
            await removeItemMutation.mutateAsync(itemToRemove.id);
            toast({
              title: "Item Removed",
              description: `Removed "${itemToRemove.text}" from your list`,
            });
          } else {
            toast({
              title: "Item Not Found", 
              description: `Couldn't find "${action.itemText}" in your lists`,
              variant: "destructive"
            });
          }
          break;

        case 'create_list':
          // Create new list first
          const newList = await createListMutation.mutateAsync({
            name: action.listName!,
            type: action.listType!
          });

          // Then add the item
          if (action.itemText) {
            await addItemMutation.mutateAsync({
              listId: newList.id,
              text: action.itemText,
              category: action.category
            });
          }

          toast({
            title: "List Created",
            description: `Created "${action.listName}" and added "${action.itemText}"`,
          });
          break;

        case 'add':
          // Find the target list
          const targetList = existingLists.find(list => list.name === action.listName);

          if (targetList && action.itemText) {
            await addItemMutation.mutateAsync({
              listId: targetList.id,
              text: action.itemText,
              category: action.category
            });

            toast({
              title: "Item Added",
              description: `Added "${action.itemText}" to ${action.listName}`,
            });
          }
          break;
      }
    } catch (error) {
      console.error('GabAi action error:', error);
      toast({
        title: "Error",
        description: "Failed to complete that action. Please try again.",
        variant: "destructive"
      });
    }
  }, [createListMutation, addItemMutation, removeItemMutation, toast]);

  return {
    analyzeUserRequest,
    executeGabAiAction,
    isProcessing: createListMutation.isPending || addItemMutation.isPending || removeItemMutation.isPending
  };
}

import { useCallback } from 'react';

interface ListContext {
  existingLists: Array<{
    id: string;
    name: string;
    type: 'shopping' | 'todo' | 'punch-list';
    itemCount: number;
  }>;
  userPreferences?: {
    defaultListType?: string;
    recentCategories?: string[];
  };
}

export function useImprovedGabAiTraining() {

  const enhancePromptWithListContext = useCallback((
    originalPrompt: string, 
    context: ListContext
  ): string => {
    const listContext = `
CONTEXT: User has these existing lists:
${context.existingLists.map(list => 
  `- ${list.name} (${list.type}, ${list.itemCount} items)`
).join('\n')}

CATEGORIZATION RULES:
1. Shopping items: groceries, food, household items, things to buy
2. Todo items: tasks, work, appointments, things to do  
3. Punch list items: repairs, fixes, maintenance, home improvements

INSTRUCTIONS:
- If user mentions shopping/buying/groceries → use shopping list
- If user mentions tasks/work/appointments → use todo list or create new todo list
- If user mentions repairs/fixes/maintenance → use punch list
- If unsure, ask user which type of list they want
- NEVER put todo tasks in shopping lists
- When creating items, specify which list type they belong in

Original request: ${originalPrompt}

Enhanced AI response with proper list categorization:`;

    return listContext;
  }, []);

  const categorizeUserRequest = useCallback((
    userInput: string,
    context: ListContext
  ): {
    suggestedListType: 'shopping' | 'todo' | 'punch-list';
    suggestedListId?: string;
    confidence: number;
    reasoning: string;
  } => {
    const input = userInput.toLowerCase();

    // Shopping indicators
    const shoppingKeywords = ['buy', 'purchase', 'grocery', 'store', 'market', 'shop', 'milk', 'bread', 'food'];
    const shoppingScore = shoppingKeywords.filter(keyword => input.includes(keyword)).length;

    // Todo indicators  
    const todoKeywords = ['task', 'work', 'meeting', 'appointment', 'call', 'email', 'finish', 'complete', 'remind'];
    const todoScore = todoKeywords.filter(keyword => input.includes(keyword)).length;

    // Punch list indicators
    const punchKeywords = ['fix', 'repair', 'broken', 'maintenance', 'replace', 'install', 'clean', 'paint'];
    const punchScore = punchKeywords.filter(keyword => input.includes(keyword)).length;

    // Determine best category
    let suggestedListType: 'shopping' | 'todo' | 'punch-list';
    let confidence: number;
    let reasoning: string;

    if (shoppingScore > todoScore && shoppingScore > punchScore) {
      suggestedListType = 'shopping';
      confidence = Math.min(0.9, 0.5 + (shoppingScore * 0.2));
      reasoning = `Detected shopping keywords: ${shoppingKeywords.filter(k => input.includes(k)).join(', ')}`;
    } else if (todoScore > punchScore) {
      suggestedListType = 'todo';
      confidence = Math.min(0.9, 0.5 + (todoScore * 0.2));
      reasoning = `Detected task keywords: ${todoKeywords.filter(k => input.includes(k)).join(', ')}`;
    } else if (punchScore > 0) {
      suggestedListType = 'punch-list';
      confidence = Math.min(0.9, 0.5 + (punchScore * 0.2));
      reasoning = `Detected maintenance keywords: ${punchKeywords.filter(k => input.includes(k)).join(', ')}`;
    } else {
      // Default to todo for ambiguous requests
      suggestedListType = 'todo';
      confidence = 0.3;
      reasoning = 'No clear category detected, defaulting to todo list';
    }

    // Find existing list of the right type
    const existingList = context.existingLists.find(list => list.type === suggestedListType);

    return {
      suggestedListType,
      suggestedListId: existingList?.id,
      confidence,
      reasoning
    };
  }, []);

