let Browser: any = null;

export function useAuth() {
  const queryClient = useQueryClient();
  const [apkAuthAttempted, setApkAuthAttempted] = React.useState(false);

  // Clean up problematic localStorage items on initialization
  React.useEffect(() => {
    const problematicKeys = [
      'gabai_mobile_token', 
      'gabai_mobile_auth_completed', 
      'gabai_mobile_auth_success',
      'gabai_mobile_redirect',
      'gabai_auth_state'
    ];

    problematicKeys.forEach(key => {
      if (localStorage.getItem(key)) {
        console.log(`🧹 Removing problematic localStorage key: ${key}`);
        localStorage.removeItem(key);
      }
    });
  }, []);

  const { data: user, isLoading, refetch, error } = useQuery({
    queryKey: ["https://gabai.ai/api/auth/user"],
    retry: false,
    staleTime: 0, // Always fresh check
    refetchOnWindowFocus: false,
    refetchOnMount: true,
    queryFn: async () => {
      try {
        console.log('🔐 Fetching user authentication...');

        // Clean up old mobile auth tokens first
        const oldMobileTokens = [
          'gabai_mobile_token', 
          'gabai_mobile_auth_completed', 
          'gabai_mobile_auth_success'
        ];
        oldMobileTokens.forEach(token => {
          if (localStorage.getItem(token)) {
            console.log(`🧹 Cleaning up old token: ${token}`);
            localStorage.removeItem(token);
          }
        });

        // Check for valid authentication token
        const authToken = localStorage.getItem('gabai_token');
        const headers: HeadersInit = {};

        if (authToken) {
          console.log('🔑 Using authentication token');
          headers['Authorization'] = `Bearer ${authToken}`;
        }

        // Create a fetch with timeout to prevent hanging
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout

        const response = await fetch("https://gabai.ai/api/auth/user", {
          headers,
          credentials: 'include', // Important for session cookies
          signal: controller.signal
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
          if (response.status === 401) {
            console.log('❌ No authenticated user');
            // Clear invalid token
            localStorage.removeItem('gabai_token');
            return null; // Not authenticated
          }
          throw new Error(`Failed to fetch user: ${response.status}`);
        }

        const userData = await response.json();
        console.log('✅ Authenticated user:', userData?.name);
        return userData as User;
      } catch (error) {
        console.error('❌ Auth fetch error:', error);

        // Log detailed error information
        if (error instanceof Error) {
          console.error('❌ Error message:', error.message);
          console.error('❌ Error name:', error.name);
        }

        // Clear any invalid tokens on error
        localStorage.removeItem('gabai_token');

        // Always return null for auth errors (don't throw)
        return null;
      }
    },
  });

  // Check for OAuth callback authentication
  React.useEffect(() => {
    const checkOAuthCallback = () => {
      const urlParams = new URLSearchParams(window.location.search);
      const tokenParam = urlParams.get('token');
      const okParam = urlParams.get('ok');

      // Handle OAuth callback with token
      if (tokenParam && okParam === '1') {
        console.log('🔐 OAuth callback detected, storing token');
        localStorage.setItem('gabai_token', tokenParam);

        // Clean up URL parameters
        const cleanUrl = window.location.pathname;
        window.history.replaceState({}, document.title, cleanUrl);

        // Refresh user data
        setTimeout(() => refetch(), 100);
      }
    };

    checkOAuthCallback();
  }, [refetch]);

  const loginMutation = useMutation({
    mutationFn: async () => {
      console.log('🔐 Starting login...');

      if (isNativeMobileApp()) {
        // For mobile app, use Capacitor browser auth flow
        console.log('📱 Mobile app: Using Capacitor OAuth flow');

        // Import and use safe deep links
        const { setupDeepLinks } = await import('@/lib/deepLinks');
        const { startCapacitorLogin } = await import('@/lib/capacitor-auth');

        // Set up safe deep link handling
        setupDeepLinks();

        return new Promise((resolve, reject) => {
          // Start the OAuth flow
          startCapacitorLogin();

          // Simple promise resolution after starting
          setTimeout(() => {
            resolve({ success: true });
          }, 1000);
        });
      } else {
        // For web, use regular redirect
        console.log('🌐 Web app: Redirecting to OAuth');
        window.location.href = "/api/auth/google";
      }
    },
    onSuccess: () => {
      // Refresh user data after successful mobile login
      queryClient.invalidateQueries({ queryKey: ["/api/auth/user"] });
    },
  });

  // Development fallback login
  const devLoginMutation = useMutation({
    mutationFn: async (credentials: { name: string; email: string }) => {
      const response = await fetch("/api/simple-login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(credentials),
      });
      if (!response.ok) {
        throw new Error("Login failed");
      }
      return response.json();
    },
    onSuccess: () => {
      // Refresh user data after successful login
      queryClient.invalidateQueries({ queryKey: ["/api/auth/user"] });
    },
  });

  const logoutMutation = useMutation({
    mutationFn: async () => {
      // Use the correct logout endpoint from auth.ts
      window.location.href = "/api/auth/logout";
    },
  });

  return {
    user,
    isLoading,
    isAuthenticated: !!user,
    login: loginMutation.mutate,
    devLogin: devLoginMutation.mutate,
    logout: logoutMutation.mutate,
    isLoggingIn: loginMutation.isPending,
    isLoggingOut: logoutMutation.isPending,
    isDevLoggingIn: devLoginMutation.isPending,
  };
}

import { useState, useEffect } from 'react';
import { auth, handleRedirectResult, onAuthChange } from '@/lib/firebase';
import { apiRequest } from '@/lib/queryClient';

interface FirebaseUser {
  id: string;
  name: string;
  email: string;
  preferences: any;
  onboardingCompleted: boolean;
}

export function useFirebaseAuth() {
  const [user, setUser] = useState<FirebaseUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    console.log('🔥 Firebase auth hook initializing');

    // Check for redirect result first
    handleRedirectResult()
      .then(async (firebaseUser) => {
        if (firebaseUser) {
          console.log('✅ Firebase user from redirect:', firebaseUser.email);
          await syncWithBackend(firebaseUser);
        }
      })
      .catch((error) => {
        console.error('❌ Firebase redirect error:', error);
        setError(error.message);
      });

    // Listen for auth state changes
    const unsubscribe = onAuthChange(async (firebaseUser) => {
      console.log('🔥 Firebase auth state changed:', firebaseUser ? firebaseUser.email : 'No user');

      if (firebaseUser) {
        await syncWithBackend(firebaseUser);
      } else {
        setUser(null);
        setIsLoading(false);
      }
    });

    return () => unsubscribe();
  }, []);

  const syncWithBackend = async (firebaseUser: any) => {
    try {
      console.log('🔄 Syncing Firebase user with backend:', firebaseUser.email);

      // Send Firebase user data to backend for user creation/login
      const response = await fetch('https://gabai.ai/api/auth/firebase-login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          uid: firebaseUser.uid,
          email: firebaseUser.email,
          name: firebaseUser.displayName || 'User',
          photoURL: firebaseUser.photoURL
        })
      });

      if (response.ok) {
        const userData = await response.json();
        console.log('✅ Backend sync successful:', userData.user.email);
        setUser(userData.user);
      } else {
        throw new Error('Backend sync failed');
      }
    } catch (error: any) {
      console.error('❌ Backend sync error:', error);
      setError(error.message);
    } finally {
      setIsLoading(false);
    }
  };

  return { user, isLoading, error };
}

import { useEffect, useState } from 'react';
import { Capacitor } from '@capacitor/core';
import { startCapacitorLogin, createAuthFetch } from '@/lib/capacitor-auth';
import { setupDeepLinks } from '@/lib/deepLinks';

export function useMobileAuth() {
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const authFetch = createAuthFetch();

  // Verify mobile token with server
  const verifyMobileToken = async (token: string) => {
    try {
      const response = await fetch('/api/auth/mobile/verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token })
      });

      if (response.ok) {
        const data = await response.json();
        setUser(data.user);
        setIsLoading(false);
        console.log('✅ Mobile auth verified:', data.user.name);
        return data.user;
      } else {
        // Token invalid, clear it
        localStorage.removeItem('gabai_token');
        setError('Authentication expired');
        setIsLoading(false);
        return null;
      }
    } catch (error) {
      console.error('❌ Mobile token verification failed:', error);
      setError('Verification failed');
      setIsLoading(false);
      return null;
    }
  };

  // Initialize auth state
  useEffect(() => {
    if (!Capacitor.isNativePlatform()) {
      // Fall back to regular auth for web
      setIsLoading(false);
      return;
    }

    console.log('📱 Initializing mobile auth...');

    // Set up safe deep link handler
    setupDeepLinks();

    // Check for existing token
    const existingToken = localStorage.getItem('gabai_token');
    if (existingToken) {
      verifyMobileToken(existingToken);
    } else {
      setIsLoading(false);
    }
  }, []);

  const login = async () => {
    if (Capacitor.isNativePlatform()) {
      setIsLoading(true);
      setError(null);
      await startCapacitorLogin();
    } else {
      // Web OAuth fallback
      window.location.href = '/api/auth/google';
    }
  };

  const logout = async () => {
    try {
      if (Capacitor.isNativePlatform()) {
        await fetch('/api/auth/mobile/logout', { method: 'POST' });
        localStorage.removeItem('gabai_token');
      } else {
        await fetch('/api/auth/logout', { method: 'POST' });
      }
      setUser(null);
      window.location.reload();
    } catch (error) {
      console.error('Logout failed:', error);
    }
  };

  return {
    user,
    isLoading,
    error,
    isAuthenticated: !!user,
    login,
    logout,
    authFetch
  };
}

import React from "react";
import type { User } from "@shared/schema";

export function useSimpleAuth() {
  const [user, setUser] = React.useState<User | null>(null);
  const [isLoading, setIsLoading] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);

  const checkAuth = React.useCallback(async () => {
    try {
      console.log('🔐 Simple auth: Checking authentication...');
      setIsLoading(true);
      setError(null);

      // Check for auth token
      const authToken = localStorage.getItem('gabai_token');
      const headers: HeadersInit = {};

      if (authToken) {
        console.log('🔑 Simple auth: Using stored token');
        headers['Authorization'] = `Bearer ${authToken}`;
      }

      const response = await fetch("/api/auth/user", {
        headers,
        credentials: 'include'
      });

      if (response.ok) {
        const userData = await response.json();
        console.log('✅ Simple auth: User authenticated:', userData?.name);
        setUser(userData);
      } else if (response.status === 401) {
        console.log('❌ Simple auth: Not authenticated');
        localStorage.removeItem('gabai_token');
        setUser(null);
      } else {
        throw new Error(`Auth check failed: ${response.status}`);
      }
    } catch (err) {
      console.error('❌ Simple auth error:', err);
      setError(err instanceof Error ? err.message : 'Auth check failed');
      setUser(null);
      localStorage.removeItem('gabai_token');
    } finally {
      setIsLoading(false);
    }
  }, []);

  React.useEffect(() => {
    checkAuth();
  }, [checkAuth]);

  return {
    user,
    isLoading,
    error,
    refetch: checkAuth
  };
}

