      description: `Quick timer set for ${minutes} minutes`,
      date: timerDate,
      recurring: 'none',
      vibration: true,
      sound: 'default'
    });

    if (alarmId) {
      toast({
        title: "Timer Set",
        description: `${minutes} minute timer started`,
