interface AnalyticsData {
  // Basic metrics
  totalUsers: string;
  totalMessages: string;
  totalLists: string;
  linkClicks: number;
  timestamp: string;

  // Enhanced user analytics
  userGrowth: {
    daily: number;
    weekly: number;
    monthly: number;
  };
  usersByLocation: Array<{
    country: string;
    region: string;
    count: number;
    percentage: number;
  }>;
  usersByTimezone: Array<{
    timezone: string;
    count: number;
    percentage: number;
  }>;
  userDemographics: {
    averageAge: number;
    professions: Array<{ profession: string; count: number; }>;
    onboardingCompletion: number;
  };

  // Conversation analytics
  conversationMetrics: {
    totalConversations: number;
    averageMessagesPerConversation: number;
    averageResponseTime: number;
    topTopics: Array<{ topic: string; frequency: number; }>;
    voiceUsagePercent: number;
    messagesLast24h: number;
    messagesLast7d: number;
    messagesLast30d: number;
  };

  // Feature usage
  featureUsage: {
    smartListsCreated: number;
    remindersSet: number;
    voiceTranscriptions: number;
    linksShortenedToday: number;
    ocrProcessed: number;
    contactsCreated: number;
  };

  // Revenue analytics
  revenueMetrics: {
    totalRevenue: number;
    revenueToday: number;
    revenueThisMonth: number;
    topPerformingLinks: Array<{
      domain: string;
      clicks: number;
      revenue: number;
    }>;
    conversionRate: number;
    averageCommission: number;
  };

  // System performance
  systemMetrics: {
    uptime: number;
    apiResponseTime: number;
    errorRate: number;
    databaseConnections: number;
    storageUsed: number;
    openaiApiCalls: number;
    elevenlabsCalls: number;
  };

  // Real-time data
  realTimeMetrics: {
    activeUsers: number;
    onlineUsers: number;
    currentConversations: number;
    averageSessionDuration: number;
  };

  // User profiles data
  userProfiles: Array<{
    id: string;
    name: string;
    email: string;
    age?: number;
    location?: string;
    profession?: string;
    timezone: string;
    preferences: any;
    onboardingCompleted: boolean;
    createdAt: string;
    updatedAt: string;
    lastActive: string;
    messageCount: number;
    listCount: number;
    reminderCount: number;
    contactCount: number;
    voiceUsagePercent: number;
    favoriteFeatures: string[];
  }>;
}

function UserProfilesTable() {
  const [selectedUser, setSelectedUser] = useState<string | null>(null);
  const { data: profiles, isLoading, error: profilesError } = useQuery<Array<{
    id: string;
    name: string;
    email: string;
    age?: number;
    location?: string;
    profession?: string;
    timezone: string;
    preferences: any;
    onboardingCompleted: boolean;
    createdAt: string;
    updatedAt: string;
    lastActive: string;
    messageCount: number;
    listCount: number;
    reminderCount: number;
    contactCount: number;
    voiceUsagePercent: number;
    favoriteFeatures: string[];
  }>>({
    queryKey: ["/api/analytics/user-profiles"],
    refetchInterval: 60000, // Refresh every minute
    retry: false,
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <div className="text-center">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-sm text-gray-600 dark:text-gray-400">Loading user profiles...</p>
        </div>
      </div>
    );
  }

  if (profilesError) {
