    console.log('🔍 Button should show:', import.meta.env.DEV && shouldUseMobileBypass() ? "Continue to GabAi (Dev)" : "Continue with Google");

    const handler = (e: Event) => {
      e.preventDefault();
      console.log('🎯 PWA install prompt available!');
      setDeferredPrompt(e);
      setShowInstallPrompt(true);
    };

    window.addEventListener('beforeinstallprompt', handler);

    // Always show install option for Android and other devices
    setTimeout(() => {
      console.log('📱 Showing install option for all devices');
      console.log('📱 Current showInstallPrompt state:', showInstallPrompt);
      setShowInstallPrompt(true);
    }, 1000);

    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  // Initialize safe deep link handling
  useEffect(() => {
    console.log('🔗 Setting up safe deep link handler');
    setupDeepLinks();
  }, []);

  const handleInstallClick = async () => {
