// Automatic authentication for VoltBuilder APK
export async function triggerAPKAuthentication() {
  console.log('🚀 APK Auto-auth: Starting authentication...');

  try {
    const response = await fetch('/api/auth/mobile-bypass', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      credentials: 'include', // Important for cookies
      body: JSON.stringify({
        deviceInfo: {
          userAgent: navigator.userAgent,
          platform: navigator.platform,
          timestamp: new Date().toISOString(),
          apkMode: true
        }
      })
    });

    if (response.ok) {
      const result = await response.json();
      console.log('✅ APK Auto-auth: Success', result.message);
      return result;
    } else {
      const error = await response.text();
      console.error('❌ APK Auto-auth: Failed', response.status, error);
      return null;
    }
  } catch (error) {
    console.error('❌ APK Auto-auth: Exception', error);
    return null;
  }
}

export function isVoltBuilderAPK(): boolean {
  const userAgent = navigator.userAgent || '';
  return userAgent.includes('wv') && 
         userAgent.includes('Android') && 
         userAgent.includes('Chrome');
}

export function shouldAutoAuth(): boolean {
  return isVoltBuilderAPK() || 
         (import.meta.env.DEV && /Mobile|Android/i.test(navigator.userAgent));
}

// Utility to detect if app is running in Capacitor native environment
export function isNativeApp(): boolean {
  // Check for Capacitor platform first
  if ((window as any).Capacitor?.isNativePlatform?.()) {
    return true;
  }

  // Check URL protocols
  if (window.location.protocol === 'capacitor:' || window.location.protocol === 'ionic:') {
    return true;
  }

  // Check for APK WebView indicators
  const userAgent = navigator.userAgent;
  const isWebView = userAgent.includes('wv') || // Android WebView
                    userAgent.includes('Version/') && userAgent.includes('Mobile Safari') || // APK WebView
                    (window as any).AndroidInterface; // Custom Android interface

  // Check for file:// protocol (often used in APK)
  const isFileProtocol = window.location.protocol === 'file:';

  console.log('🔍 Native app detection:', {
    capacitor: !!(window as any).Capacitor?.isNativePlatform?.(),
    protocol: window.location.protocol,
    userAgent: userAgent.substring(0, 50),
    webView: isWebView,
    fileProtocol: isFileProtocol
  });

  return isWebView || isFileProtocol;
}

export function isMobileDevice(): boolean {
  return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
}

// Check if running in native mobile app
export function isNativeMobileApp(): boolean {
  return isNativeApp() && isMobileDevice();
}

// Currency utility functions for handling monetary amounts

/**
 * Format cents to dollar string (e.g., 1250 -> "$12.50")
 */
export function formatCurrency(cents: number | null | undefined, currency: string = "USD"): string {
  if (cents === null || cents === undefined) return "";

  const formatter = new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: currency,
    minimumFractionDigits: 2,
  });

  return formatter.format(cents / 100);
}

/**
 * Parse dollar string to cents (e.g., "$12.50" -> 1250, "12.5" -> 1250)
 */
export function parseCurrency(value: string): number | null {
  if (!value || value.trim() === "") return null;

  // Remove currency symbols and spaces
  const cleaned = value.replace(/[$,\s]/g, '');

  // Parse as float and convert to cents
  const dollars = parseFloat(cleaned);
  if (isNaN(dollars)) return null;

  return Math.round(dollars * 100);
}

/**
 * Format input value for currency display
 */
export function formatCurrencyInput(value: string): string {
  const cents = parseCurrency(value);
  if (cents === null) return value;

  const dollars = cents / 100;
  return dollars.toFixed(2);
}

/**
 * Calculate total from array of amounts
 */
export function calculateTotal(amounts: (number | null | undefined)[]): number {
  return amounts.reduce<number>((sum, amount) => {
    return sum + (amount || 0);
  }, 0);
}

/**
 * Validate currency input
 */
export function isValidCurrency(value: string): boolean {
  if (!value || value.trim() === "") return true; // Empty is valid

  const cents = parseCurrency(value);
  return cents !== null && cents >= 0;
}

