    return null;
  }
}

// Fix mobile content rendering issues
export function fixMobileContent() {
  if (typeof window === 'undefined') return;

  // Fix character encoding issues
  document.documentElement.setAttribute('lang', 'en');
  document.documentElement.setAttribute('dir', 'ltr');

  // Remove problematic scripts that cause rendering issues
  const problematicScripts = document.querySelectorAll('script[src*="vite"], script[src*="replit"], script[src*="runtime-error"]');
  problematicScripts.forEach(script => {
    if (script.parentNode) {
      script.parentNode.removeChild(script);
    }
  });

  // Force proper viewport
  const viewport = document.querySelector('meta[name="viewport"]');
  if (viewport) {
    viewport.setAttribute('content', 'width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no');
  }

  // Fix text rendering
  document.body.style.fontFamily = 'system-ui, -apple-system, sans-serif';
  document.body.style.fontSize = '16px';
  document.body.style.lineHeight = '1.5';

  console.log('📱 Mobile content fixes applied');
}

// Apply fixes immediately when module loads
if (typeof window !== 'undefined') {
  fixMobileContent();

  // Also apply on DOM content loaded
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', fixMobileContent);
  }
}

// Mobile debugging utilities
export function addMobileDebugInfo() {
  if (typeof window === 'undefined') return;

  console.log('🔧 MOBILE DEBUG INFO:');
  console.log('📱 User Agent:', navigator.userAgent);
  console.log('🌐 Location:', window.location.href);
  console.log('🔗 Origin:', window.location.origin);
  console.log('📊 Screen:', window.screen.width + 'x' + window.screen.height);
  console.log('📱 Platform Detection:', {
    isMobile: /Mobile|Android|iPhone|iPad/.test(navigator.userAgent),
    isAndroid: /Android/.test(navigator.userAgent),
    isIOS: /iPhone|iPad/.test(navigator.userAgent),
    isCapacitor: window.location.protocol === 'capacitor:'
  });
}

export function logAuthState(user: any, isLoading: boolean) {
  console.log('🔐 AUTH STATE:', {
    hasUser: !!user,
    isLoading,
    userEmail: user?.email,
    timestamp: new Date().toISOString()
  });
}

// Text rendering utilities to prevent backwards or broken text display

export function detectTextDirection(text: string): 'ltr' | 'rtl' | 'auto' {
  if (!text) return 'auto';

  // Hebrew unicode range: \u0590-\u05FF
  // Arabic unicode range: \u0600-\u06FF
  const rtlRegex = /[\u0590-\u05FF\u0600-\u06FF]/;

  if (rtlRegex.test(text)) {
    return 'rtl';
  }

  return 'ltr';
}

export function safeTextRender(text: string | null | undefined): string {
  if (!text) return '';
  if (typeof text !== 'string') return String(text);

  // Only remove harmful control characters, keep natural RTL/LTR for proper languages
  return text
    .replace(/[\u0000-\u001F\u007F-\u009F]/g, '') // Remove control characters
    .trim();
}

export function isTextReady(text: string | null | undefined): boolean {
  return Boolean(text && typeof text === 'string' && text.trim().length > 0);
}

export function sanitizeForDisplay(text: string): string {
  if (!text || typeof text !== 'string') return '';

  // Basic sanitization to prevent display issues
  return text
    .replace(/[\u0000-\u001F\u007F-\u009F]/g, '') // Remove control characters
    .replace(/\r\n/g, '\n') // Normalize line endings
    .replace(/\r/g, '\n')
    .trim();
}

