  const [calculatedTotal, setCalculatedTotal] = useState<{ listId: string; total: number } | null>(null);

  const queryClient = useQueryClient();
  const { toast } = useToast();

  // Unified data queries for both web and mobile
  const { isRecording, startRecording, stopRecording, isTranscribing } = useVoice({
    onTranscriptionComplete: (text) => {
      if (selectedListId && text.trim()) {
        setNewItemName(text);
        handleAddItem(selectedListId);
      }
      setIsVoiceAddingItem(false);
    },
    onError: (error) => {
      toast({
        title: "Voice Error", 
        description: error,
        variant: "destructive",
      });
      setIsVoiceAddingItem(false);
    },
  });

  // Unified smart lists query for both web and mobile
  const { data: lists = [], isLoading, error } = useQuery<(SmartList & { items: ListItem[] })[]>({
    queryKey: ["/api/smart-lists", user.id],
    queryFn: () => api.getSmartLists(user.id),
    enabled: !!user?.id
  });



  // Create list mutation (unified for web and mobile)
  const createListMutation = useMutation({
    mutationFn: () => api.createSmartList({
      userId: user.id,
      name: newListName,
      type: newListType,
      description: newListDescription,
      isShared,
      categories: listTypeTemplates[newListType].categories,
      sortBy: "category"
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      setNewListName("");
      setNewListDescription("");
      setIsShared(false);
      toast({
        title: "List created!",
        description: `Your ${listTypeTemplates[newListType].name.toLowerCase()} has been created.`,
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to create list",
        variant: "destructive",
      });
    },
  });

  // Create item mutation
  const createItemMutation = useMutation({
    mutationFn: ({ listId, name, category, assignedTo, amount, currency, quantity, unit }: {
      listId: string;
      name: string;
      category: string;
      assignedTo?: string;
      amount?: number | null;
      currency?: string;
      quantity?: number;
      unit?: string;
    }) => {
      console.log('Creating item with data:', { listId, name, category, assignedTo, amount, currency, quantity, unit });

      if (isNativeApp()) {
        // Mobile mode - use direct API call since mobileItemsQuery is not available
        return api.createListItem({
          listId,
          name,
          category,
          priority: 1,
          assignedTo: assignedTo || undefined,
          addedBy: user.name || user.id,
          amount,
          currency,
          quantity,
          unit,
        });
      }

      return api.createListItem({
        listId,
        name,
        category,
        priority: 1,
        assignedTo: assignedTo || undefined,
        addedBy: user.name || user.id,
        amount,
        currency,
        quantity,
        unit,
      });
    },
    onSuccess: () => {
      if (!isNativeApp()) {
        queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      }
      setNewItemName("");
      setNewItemCategory("");
      setNewItemAssignedTo("");
      setNewItemAmount("");
      setNewItemQuantity("1");
      setNewItemUnit("");
      setSelectedListId(null);
      toast({
        title: "Item added!",
        description: "Item has been added to your list.",
      });
    },
    onError: (error) => {
      toast({
        title: "Error adding item",
        description: error.message || "Failed to add item to list",
        variant: "destructive",
      });
    },
  });

  // Update item mutation
  const updateItemMutation = useMutation({
    mutationFn: ({ id, name, category, amount }: {
      id: string;
      name: string;
      category: string;
      amount?: string;
    }) => {
      const updateData: any = { name, category };

      if (amount && amount.trim()) {
        const parsedAmount = parseCurrency(amount);
        if (parsedAmount !== null) {
          updateData.amount = parsedAmount;
          updateData.currency = "USD";
        }
      }

      return api.updateListItem(id, updateData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      setEditingItem(null);
      toast({
        title: "Item updated!",
        description: "Item has been updated successfully.",
      });
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update item",
        variant: "destructive",
      });
    },
  });

  // Delete list mutation
  const deleteListMutation = useMutation({
    mutationFn: (listId: string) => api.deleteSmartList(listId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      setListToDelete(null);
      if (activeTab !== "all") {
        setActiveTab("all"); // Switch to "all" view if current tab was deleted
      }
      toast({
        title: "List deleted!",
        description: "The list has been permanently removed.",
      });
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: error.message || "Failed to delete list",
        variant: "destructive",
      });
    },
  });

  // Reorder items mutation
  const reorderItemsMutation = useMutation({
    mutationFn: async ({ items }: { items: { id: string; position: number }[] }) => {
      // Update positions for multiple items at once
      const updates = items.map(item => 
        api.updateListItem(item.id, { position: item.position })
      );
      await Promise.all(updates);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
    },
    onError: (error) => {
      toast({
        title: "Error reordering items",
        description: error.message || "Failed to reorder items",
        variant: "destructive",
      });
    },
  });

  // Smart relabel mutation
  const relabelListMutation = useMutation({
    mutationFn: async (listId: string) => {
      const list = lists.find(l => l.id === listId);
      if (!list) throw new Error('List not found');

      // Send items to AI for smart naming
      const response = await fetch('/api/relabel-list', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          listId,
          currentName: list.name,
          items: list.items.map(item => item.name),
          listType: list.type
        })
      });

      if (!response.ok) throw new Error('Failed to relabel list');
      return response.json();
    },
    onSuccess: (result) => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      toast({
        title: "List renamed!",
        description: `List renamed to: ${result.newName}`,
      });
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: error.message || "Failed to rename list",
        variant: "destructive",
      });
    },
  });

  // Calculate total function for non-currency lists
  const calculateListTotal = (list: any) => {
    let total = 0;
    list.items.forEach((item: any) => {
      const matches = item.name.match(/\$?([\d,]+\.?\d*)/g);
      if (matches) {
        matches.forEach((match: string) => {
          const amount = parseFloat(match.replace(/[$,]/g, ''));
          if (!isNaN(amount)) total += amount;
        });
      }
    });

    setCalculatedTotal({ listId: list.id, total });
    toast({
      title: "Total Calculated",
      description: `Total for ${list.name}: $${total.toFixed(2)}`,
    });
  };

  // Drag sensors for touch and mouse with improved touch handling
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8, // Require 8px movement before starting drag
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // Handle drag end - Enhanced cross-category support
  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    // Always restore body scroll when drag ends
    document.body.style.overflow = '';

    if (!over || active.id === over.id) {
      return;
    }

    // Find the source list and item
    const sourceList = lists.find(list => 
      list.items.some(item => item.id === active.id)
    );

    if (!sourceList) return;

    const draggedItem = sourceList.items.find(item => item.id === active.id);
    const targetItem = sourceList.items.find(item => item.id === over.id);

    if (!draggedItem || !targetItem) return;

    // Allow cross-category rearrangement
    const allItems = [...sourceList.items].sort((a, b) => (a.position || 0) - (b.position || 0));
    const oldIndex = allItems.findIndex(item => item.id === active.id);
    const newIndex = allItems.findIndex(item => item.id === over.id);

    if (oldIndex !== newIndex) {
      const newOrder = arrayMove(allItems, oldIndex, newIndex);

      // Update positions for all items
      const updatedItems = newOrder.map((item, index) => ({
        id: item.id,
        position: index
      }));

      reorderItemsMutation.mutate({ items: updatedItems });

      toast({
        title: "Item moved",
        description: `"${draggedItem.name}" repositioned successfully`,
      });
    }
  };

  // Share list mutation
  const shareListMutation = useMutation({
    mutationFn: (listId: string) => api.shareList(listId),
    onSuccess: (data) => {
      setShareCode(data.shareCode);
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      toast({
        title: "List shared!",
        description: "Your list is now shareable. Copy the link to invite collaborators.",
      });
    },
  });

  // Join shared list mutation
  const joinListMutation = useMutation({
    mutationFn: () => api.joinSharedList(shareCode, user.id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
      setShareCode("");
      toast({
        title: "Joined list!",
        description: "You've successfully joined the shared list.",
      });
    },
  });

  // Toggle item completion mutation
  const toggleItemMutation = useMutation({
    mutationFn: (itemId: string) => api.toggleListItem(itemId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
    },
  });

  // Delete item mutation
  const deleteItemMutation = useMutation({
    mutationFn: (itemId: string) => api.deleteListItem(itemId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/smart-lists", user.id] });
    },
  });

  const handleCreateList = () => {
    if (!newListName.trim()) {
      console.log("⚠️ Cannot create list: name is empty");
      toast({
        title: "List name required",
        description: "Please enter a name for your list",
        variant: "destructive",
      });
      return;
    }

    console.log("📝 Creating list with data:", {
      userId: user.id,
      name: newListName,
      type: newListType,
      description: newListDescription,
      isShared,
      categories: listTypeTemplates[newListType].categories,
      sortBy: "category"
    });

    createListMutation.mutate();
  };

  const handleAddItem = async (listId: string) => {
    if (!newItemName.trim()) return;
    if (createItemMutation.isPending) return; // Prevent duplicate submissions

    const selectedList = lists.find(list => list.id === listId);
    if (!selectedList) return;

    // Use AI-powered smart categorization for shopping items
    let category = "Other";

    if (selectedList.type === "shopping") {
      // Call AI categorization API for intelligent grocery categorization
      try {
        const response = await fetch('/api/categorize-item', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            itemName: newItemName,
            listType: 'shopping'
          })
        });

        if (response.ok) {
          const result = await response.json();
          category = result.category || "Other";
        } else {
          // Fallback to simple categorization if AI fails
          category = getSimpleCategory(newItemName.toLowerCase());
        }
      } catch (error) {
        console.error('AI categorization failed, using fallback:', error);
        category = getSimpleCategory(newItemName.toLowerCase());
      }
    } else if (selectedList.type === "punch_list") {
      const punchCategories = {
        "Plumbing": ["plumb", "pipe", "drain", "faucet", "toilet", "shower", "sink"],
        "Electrical": ["electric", "wire", "outlet", "switch", "light", "circuit"],
        "Painting": ["paint", "brush", "roller", "primer", "wall"],
        "General": ["fix", "repair", "install", "replace"]
      };

      for (const [cat, items] of Object.entries(punchCategories)) {
        if (items.some(work => newItemName.toLowerCase().includes(work))) {
          category = cat;
          break;
        }
      }
    }

    setSelectedListId(listId);

    const template = listTypeTemplates[selectedList.type as keyof typeof listTypeTemplates];
    const amount = (template as any)?.supportsCurrency ? parseCurrency(newItemAmount) : null;

    createItemMutation.mutate({
      listId,
      name: newItemName,
      category,
      assignedTo: selectedList.type === "punch_list" ? newItemAssignedTo : undefined,
      amount: amount,
      currency: amount ? "USD" : undefined,
      quantity: selectedList.type === "shopping" && newItemQuantity ? parseInt(newItemQuantity) : 1,
      unit: selectedList.type === "shopping" && newItemUnit ? newItemUnit : undefined,
    });
  };

  const handleVoiceAddItem = async (listId: string) => {
    if (isVoiceAddingItem || createItemMutation.isPending) return; // Prevent duplicate voice operations

    setIsVoiceAddingItem(true);
    setSelectedListId(listId);

    try {
      if (isRecording) {
        // Stop recording if already recording
        stopRecording();
      } else {
        // Start recording
        startRecording();
      }
    } catch (error) {
      toast({
        title: "Voice Error",
        description: "Failed to record voice input",
        variant: "destructive",
      });
      setIsVoiceAddingItem(false);
    }
  };

  const copyShareLink = (code: string) => {
    const url = `${window.location.origin}/shared/${code}`;
    navigator.clipboard.writeText(url);
    toast({
      title: "Link copied!",
      description: "Share this link with collaborators",
    });
  };

  const shareViaWhatsApp = (shareCode: string, listName: string) => {
    const url = `${window.location.origin}/shared/${shareCode}`;
    const message = `Hey! I'm sharing my "${listName}" list with you via GabAi. You can view and collaborate here: ${url}`;
    const whatsappUrl = `https://wa.me/?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const shareViaSMS = (shareCode: string, listName: string) => {
    const url = `${window.location.origin}/shared/${shareCode}`;
    const message = `Hey! I'm sharing my "${listName}" list with you via GabAi: ${url}`;
    const smsUrl = `sms:?body=${encodeURIComponent(message)}`;
    window.open(smsUrl);
  };

  const shareViaEmail = (shareCode: string, listName: string) => {
    const url = `${window.location.origin}/shared/${shareCode}`;
    const subject = encodeURIComponent(`${listName} - Shared List`);
    const body = encodeURIComponent(`Hi there!\n\nI'm sharing my "${listName}" list with you through GabAi. You can view and collaborate on this list by clicking the link below:\n\n${url}\n\nBest regards!`);
    const emailUrl = `mailto:?subject=${subject}&body=${body}`;
    window.open(emailUrl, '_self');
  };

  const sortItemsByCategory = (items: ListItem[], categories: string[]) => {
    const categorized = categories.map(category => ({
      category,
      items: items.filter(item => item.category === category)
    })).filter(group => group.items.length > 0);

    const uncategorized = items.filter(item => !item.category || !categories.includes(item.category));
    if (uncategorized.length > 0) {
      categorized.push({ category: "Other", items: uncategorized });
    }

    return categorized;
  };

  if (isLoading) {
    return (
      <div className="p-4 space-y-4">
        <Skeleton className="h-8 w-48" />
        {[1, 2, 3].map((i) => (
          <Card key={i}>
            <CardHeader>
              <Skeleton className="h-6 w-32" />
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                <Skeleton className="h-4 w-full" />
                <Skeleton className="h-4 w-3/4" />
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="border-b border-gray-200 dark:border-gray-700 p-4">
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Smart Lists</h1>
          <div className="flex items-center space-x-2">
            {/* Join Shared List */}
            <Dialog>
              <DialogTrigger asChild>
                <Button variant="outline" size="sm">
                  <Users className="h-4 w-4 mr-2" />
                  Join List
                </Button>
              </DialogTrigger>
              <DialogContent>
                <DialogHeader>
                  <DialogTitle>Join Shared List</DialogTitle>
                </DialogHeader>
                <div className="space-y-4">
                  <div>
                    <Label htmlFor="share-code">Share Code or Link</Label>
                    <Input
                      id="share-code"
                      value={shareCode}
                      onChange={(e) => setShareCode(e.target.value)}
                      placeholder="Enter share code or paste link"
                      className="mt-1"
                    />
                  </div>
                  <Button 
                    onClick={() => joinListMutation.mutate()}
                    disabled={!shareCode.trim() || joinListMutation.isPending}
                    className="w-full"
                  >
                    Join List
                  </Button>
                </div>
              </DialogContent>
            </Dialog>

            {/* Create New List */}
            <Dialog>
              <DialogTrigger asChild>
                <Button>
                  <Plus className="h-4 w-4 mr-2" />
                  New List
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-2xl">
                <DialogHeader>
                  <DialogTitle>Create New Smart List</DialogTitle>
                </DialogHeader>
                <div className="space-y-6">
                  <div>
                    <Label htmlFor="list-type">List Type</Label>
                    <Select value={newListType} onValueChange={(value: keyof typeof listTypeTemplates) => setNewListType(value)}>
                      <SelectTrigger className="mt-1">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {Object.entries(listTypeTemplates).map(([key, template]) => {
                          const Icon = template.icon;
                          return (
                            <SelectItem key={key} value={key}>
                              <div className="flex items-center space-x-2">
                                <Icon className="h-4 w-4" />
                                <span>{template.name}</span>
                              </div>
                            </SelectItem>
                          );
                        })}
                      </SelectContent>
                    </Select>
                  </div>

                  <div>
                    <Label htmlFor="list-name">List Name</Label>
                    <Input
                      id="list-name"
                      value={newListName}
                      onChange={(e) => setNewListName(e.target.value)}
                      placeholder={`e.g., ${listTypeTemplates[newListType].name}`}
                      className="mt-1"
                    />
                  </div>

                  <div>
                    <Label htmlFor="list-description">Description (optional)</Label>
                    <Textarea
                      id="list-description"
                      value={newListDescription}
                      onChange={(e) => setNewListDescription(e.target.value)}
                      placeholder="Describe what this list is for..."
                      className="mt-1"
                    />
                  </div>

                  <div className="flex items-center space-x-2">
                    <Switch
                      id="is-shared"
                      checked={isShared}
                      onCheckedChange={setIsShared}
                    />
                    <Label htmlFor="is-shared">Enable sharing and collaboration</Label>
                  </div>

                  <div className="border rounded-lg p-4 bg-gray-50 dark:bg-gray-800">
                    <h4 className="font-medium mb-2">Categories for this list type:</h4>
                    <div className="flex flex-wrap gap-2">
                      {listTypeTemplates[newListType].categories.map((category) => (
                        <Badge key={category} variant="secondary" className="text-xs">
                          {category}
                        </Badge>
                      ))}
                    </div>
                  </div>

                  <Button 
                    onClick={handleCreateList}
                    disabled={!newListName.trim() || createListMutation.isPending}
                    className="w-full"
                  >
                    Create {listTypeTemplates[newListType].name}
                  </Button>
                </div>
              </DialogContent>
            </Dialog>
          </div>
        </div>
      </div>

      {/* Scrollable List Navigation Tabs */}
      {lists.length > 0 && (
        <div className="border-b">
          <div className="px-4 py-2">
            <div className="flex items-center space-x-2 overflow-x-auto scrollbar-hide scroll-smooth pb-2" 
                 style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}>
              {/* All Lists Tab */}
              <button
                onClick={() => setActiveTab("all")}
                className={`flex items-center space-x-2 px-4 py-2 rounded-lg whitespace-nowrap transition-all ${
                  activeTab === "all"
                    ? "bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200 font-medium"
                    : "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-700"
                }`}
              >
                <ListOrdered className="h-4 w-4" />
                <span className="text-sm">All Lists</span>
                <Badge variant="secondary" className="text-xs ml-1">
                  {lists.length}
                </Badge>
              </button>

              {/* Individual List Tabs */}
              {lists.map((list) => {
                const template = listTypeTemplates[list.type as keyof typeof listTypeTemplates] || listTypeTemplates.todo;
                const Icon = template.icon;
                const isActive = activeTab === list.id;

                return (
                  <button
                    key={list.id}
                    onClick={() => setActiveTab(list.id)}
                    className={`flex items-center space-x-2 px-4 py-2 rounded-lg whitespace-nowrap transition-all ${
                      isActive
                        ? "bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200 font-medium border-2 border-blue-300 dark:border-blue-600"
                        : "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-700"
                    }`}
                  >
                    <Icon className="h-4 w-4" />
                    <span className="text-sm max-w-[120px] truncate">{list.name}</span>
                    <Badge variant="secondary" className="text-xs ml-1">
                      {list.items.filter(item => !item.completed).length}
                    </Badge>
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      )}

      {/* Lists - Fixed mobile scrolling */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 pb-32" style={{ maxHeight: 'calc(100vh - 200px)', minHeight: '400px' }}>
        {lists.length === 0 ? (
          <div className="text-center py-8">
            <p className="text-gray-500 dark:text-gray-400 mb-4">
              No lists yet. Create your first smart list!
            </p>
          </div>
        ) : (
          lists
            .filter(list => activeTab === "all" || activeTab === list.id)
            .map((list) => {
            const template = listTypeTemplates[list.type as keyof typeof listTypeTemplates] || listTypeTemplates.todo;
            const Icon = template.icon;
            const categorizedItems = sortItemsByCategory(list.items, list.categories || []);

            return (
              <Card key={list.id} className="overflow-hidden">
                <CardHeader className="pb-3">
                  {/* List Title Row */}
                  <div className="flex items-center space-x-3 mb-3">
                    <div className={`p-2 rounded-lg ${template.color}`}>
                      <Icon className="h-5 w-5" />
                    </div>
                    <div className="flex-1">
                      <CardTitle className="text-lg">{list.name}</CardTitle>
                      {list.description && (
                        <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                          {list.description}
                        </p>
                      )}
                    </div>
                  </div>

                  {/* Controls and Stats Row */}
                  <div className="flex items-center justify-between flex-wrap gap-2">
                    {/* Left side - Actions */}
                    <div className="flex items-center space-x-2">
                      {list.isShared ? (
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="outline" size="sm" className="smart-list-button">
                              <Share2 className="h-4 w-4 mr-1" />
                              Share
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent>
                            <DropdownMenuItem onClick={() => copyShareLink(list.shareCode!)}>
                              <Link className="h-4 w-4 mr-2" />
                              Copy Link
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => shareViaWhatsApp(list.shareCode!, list.name)}>
                              <MessageCircle className="h-4 w-4 mr-2" />
                              Share via WhatsApp
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => shareViaSMS(list.shareCode!, list.name)}>
                              <MessageSquare className="h-4 w-4 mr-2" />
                              Share via SMS
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => shareViaEmail(list.shareCode!, list.name)}>
                              <Mail className="h-4 w-4 mr-2" />
                              Share via Email
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      ) : (
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => shareListMutation.mutate(list.id)}
                          disabled={shareListMutation.isPending}
                          className="smart-list-button"
                        >
                          <Share2 className="h-4 w-4 mr-1" />
                          {shareListMutation.isPending ? "..." : "Share"}
                        </Button>
                      )}

                      {/* Delete List Button */}
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setListToDelete(list.id)}
                        className="text-red-600 hover:text-red-700 hover:bg-red-50 dark:text-red-400 dark:hover:bg-red-900/20 smart-list-button"
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>

                    {/* Right side - Stats and Info */}
                    <div className="flex items-center space-x-2 flex-wrap">
                      <Badge variant="outline" className="text-xs">
                        {list.items.length} items
                      </Badge>
                      {(template as any)?.supportsCurrency && (
                        <Badge variant="outline" className="text-xs text-emerald-600 dark:text-emerald-400">
                          Total: {formatCurrency(calculateTotal(list.items.map(item => item.amount)))}
                        </Badge>
                      )}

                      {/* Calculated total display for non-currency lists */}
                      {calculatedTotal && calculatedTotal.listId === list.id && (
                        <Badge variant="outline" className="text-xs text-blue-600 dark:text-blue-400">
                          Calculated Total: ${calculatedTotal.total.toFixed(2)}
                        </Badge>
                      )}

                      {/* Smart Relabel Button */}
                      <Button
                        variant="outline" 
                        size="sm"
                        onClick={() => relabelListMutation.mutate(list.id)}
                        disabled={relabelListMutation.isPending}
                        className="text-xs smart-list-button"
                      >
                        {relabelListMutation.isPending ? "..." : "Smart Name"}
                      </Button>

                      {/* Calculate Total Button for non-currency lists */}
                      {!(template as any)?.supportsCurrency && list.items.some(item => /\$[\d,]+\.?\d*|\d+\.?\d*\s*dollar|price|cost/i.test(item.name)) && (
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => calculateListTotal(list)}
                          className="text-xs text-blue-600 dark:text-blue-400 smart-list-button"
                        >
                          Calculate Total
                        </Button>
                      )}
                    </div>
                  </div>
                </CardHeader>

                <CardContent className="space-y-4">
                  {/* Add Item Section */}
                  <div className="border rounded-lg p-4 bg-gray-50 dark:bg-gray-800 smart-list-input-container">
                    {/* Main input row */}
                    <div className="flex items-center space-x-3 mb-3">
                      <Input
                        value={newItemName}
                        onChange={(e) => setNewItemName(e.target.value)}
                        placeholder="Add new item..."
                        className="flex-1 text-base font-normal smart-list-input !text-base !min-h-[48px] !h-[48px] !py-3 !px-4"
                        style={{ 
                          fontSize: '16px',
                          minHeight: '48px',
                          height: '48px',
                          lineHeight: '1.4',
                          padding: '12px 16px',
                          direction: 'ltr',
                          unicodeBidi: 'normal',
                          textAlign: 'left'
                        }}
                        onKeyDown={(e) => {
                          if (e.key === "Enter" && newItemName.trim()) {
                            e.preventDefault();
                            handleAddItem(list.id);
                          }
                        }}
                      />
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleVoiceAddItem(list.id)}
                        disabled={isRecording || isTranscribing}
                        className="smart-list-voice-button min-w-[48px]"
                        title="Add item by voice"
                      >
                        <Mic className="h-5 w-5" />
                      </Button>
                      <Button
                        size="sm"
                        onClick={() => handleAddItem(list.id)}
                        disabled={!newItemName.trim()}
                        className="smart-list-button min-w-[48px] bg-blue-600 hover:bg-blue-700 text-white"
                        title="Add item"
                      >
                        <Plus className="h-5 w-5" />
                      </Button>
                    </div>

                    {/* Category and options row */}
                    <div className="flex items-center space-x-3">
                      <Select 
                        value={newItemCategory} 
                        onValueChange={setNewItemCategory}
                      >
                        <SelectTrigger className="flex-1 min-h-[44px]">
                          <SelectValue placeholder="Select category" />
                        </SelectTrigger>
                        <SelectContent>
                          {(list.categories || []).map((category) => (
                            <SelectItem key={category} value={category}>
                              {category}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>

                    {list.type === "punch_list" && (
                      <Input
                        value={newItemAssignedTo}
                        onChange={(e) => setNewItemAssignedTo(e.target.value)}
                        placeholder="Assign to (e.g., John the Plumber)"
                        className="text-sm smart-list-input"
                        style={{ 
                          fontSize: '16px', 
                          minHeight: '44px', 
                          height: '44px',
                          direction: 'ltr',
                          unicodeBidi: 'normal',
                          textAlign: 'left'
                        }}
                      />
                    )}

                    {/* Currency Input for Payment/Budget Lists */}
                    {(template as any)?.supportsCurrency && (
                      <div className="flex items-center space-x-2">
                        <DollarSign className="h-4 w-4 text-gray-500" />
                        <Input
                          value={newItemAmount}
                          onChange={(e) => {
                            const value = e.target.value;
                            if (isValidCurrency(value) || value === '') {
                              setNewItemAmount(value);
                            }
                          }}
                          onBlur={() => {
                            if (newItemAmount && isValidCurrency(newItemAmount)) {
                              setNewItemAmount(formatCurrencyInput(newItemAmount));
                            }
                          }}
                          placeholder="Amount (e.g., 150.00)"
                          className="text-sm smart-list-input"
                          style={{ 
                            fontSize: '16px', 
                            minHeight: '44px', 
                            height: '44px',
                            direction: 'ltr',
                            unicodeBidi: 'normal',
                            textAlign: 'left'
                          }}
                        />
                      </div>
                    )}

                    {/* Quantity and Unit Input for Shopping Lists */}
                    {list.type === "shopping" && (
                      <div className="flex items-center space-x-2">
                        <Hash className="h-4 w-4 text-gray-500" />
                        <Input
                          value={newItemQuantity}
                          onChange={(e) => setNewItemQuantity(e.target.value)}
                          placeholder="Qty (e.g., 2)"
                          className="text-sm smart-list-input w-20"
                          type="number"
                          min="1"
                          style={{ 
                            fontSize: '16px', 
                            minHeight: '44px', 
                            height: '44px',
                            direction: 'ltr',
                            unicodeBidi: 'normal',
                            textAlign: 'left'
                          }}
                        />
                        <Input
                          value={newItemUnit}
                          onChange={(e) => setNewItemUnit(e.target.value)}
                          placeholder="Unit (e.g., lbs, pieces)"
                          className="text-sm smart-list-input flex-1"
                          style={{ 
                            fontSize: '16px', 
                            minHeight: '44px', 
                            height: '44px',
                            direction: 'ltr',
                            unicodeBidi: 'normal',
                            textAlign: 'left'
                          }}
                        />
                      </div>
                    )}
                  </div>

                  {/* Items by Category with Drag and Drop */}
                  {categorizedItems.length > 0 ? (
                    <DndContext
                      sensors={sensors}
                      collisionDetection={closestCenter}
                      onDragEnd={handleDragEnd}
                      onDragStart={() => {
                        // Disable body scroll during drag
                        document.body.style.overflow = 'hidden';
                      }}
                      onDragCancel={() => {
                        // Restore body scroll if drag is cancelled
                        document.body.style.overflow = '';
                      }}
                    >
                      <div className="space-y-4">
                        {categorizedItems.map(({ category, items }) => {
                          // Sort items by position for consistent ordering
                          const sortedItems = [...items].sort((a, b) => (a.position || 0) - (b.position || 0));

                          return (
                            <div key={category}>
                              <h4 className="font-medium text-sm text-gray-700 dark:text-gray-300 mb-2 flex items-center justify-between smart-list-category-header">
                                <div className="flex items-center">
                                  {/* Category Icon in Header */}
                                  {(() => {
                                    const Icon = getCategoryIcon(category);
                                    return <Icon className={`h-4 w-4 mr-2 ${getCategoryColor(category)}`} />;
                                  })()}
                                  <span className="mr-2">{category}</span>
                                  <Badge variant="secondary" className="text-xs">
                                    {items.filter(item => !item.completed).length}
                                  </Badge>
                                </div>
                                {(template as any)?.supportsCurrency && (
                                  <span className="text-xs font-medium text-emerald-600 dark:text-emerald-400">
                                    Total: {formatCurrency(calculateTotal(items.map(item => item.amount)))}
                                  </span>
                                )}
                              </h4>

                              <SortableContext 
                                items={sortedItems.map(item => item.id)}
                                strategy={verticalListSortingStrategy}
                              >
                                <div className="space-y-2">
                                  {sortedItems.map((item) => (
                                    <SortableItem
                                      key={item.id}
                                      item={item}
                                      onToggle={() => toggleItemMutation.mutate(item.id)}
                                      onDelete={() => deleteItemMutation.mutate(item.id)}
                                      onEdit={(id, name, category, amount) => {
                                        if (editingItem?.id === id) {
                                          // Save or cancel editing
                                          if (name !== item.name || category !== (item.category || "Other") || amount !== (item.amount ? formatCurrency(item.amount, item.currency || "USD") : "")) {
                                            updateItemMutation.mutate({ id, name, category, amount });
                                          } else {
                                            setEditingItem(null);
                                          }
                                        } else {
                                          // Start editing
                                          setEditingItem({ id, name, category, amount });
                                        }
                                      }}
                                      showCurrency={(template as any)?.supportsCurrency}
                                      categories={list.categories || ["Other"]}
                                      isEditing={editingItem?.id === item.id}
                                    />
                                  ))}
                                </div>
                              </SortableContext>
                            </div>
                          );
                        })}
                      </div>
                    </DndContext>
                  ) : (
                    <p className="text-gray-500 dark:text-gray-400 text-center py-4">
                      No items yet. Add your first item above!
                    </p>
                  )}
                </CardContent>
              </Card>
            );
          })
        )}
      </div>

      {/* Delete List Confirmation Dialog */}
      <Dialog open={!!listToDelete} onOpenChange={() => setListToDelete(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Delete List</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <p className="text-gray-600 dark:text-gray-300">
              Are you sure you want to delete this list? This action cannot be undone and will permanently remove all items in the list.
            </p>
            <div className="flex justify-end space-x-2">
              <Button
                variant="outline"
                onClick={() => setListToDelete(null)}
              >
                Cancel
              </Button>
              <Button
                variant="destructive"
                onClick={() => {
                  if (listToDelete) {
                    deleteListMutation.mutate(listToDelete);
                  }
                }}
                disabled={deleteListMutation.isPending}
              >
                {deleteListMutation.isPending ? "Deleting..." : "Delete List"}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Plus, Mic, Send, Trash2, Check, X, GripVertical } from "lucide-react";
import { useAuth } from "@/hooks/useAuth";
import { api } from "@/lib/api";
import { useToast } from "@/hooks/use-toast";
import { useVoice } from "@/hooks/use-voice";
import { 
  DndContext, 
  closestCenter, 
  KeyboardSensor, 
  PointerSensor, 
  useSensor, 
  useSensors,
  DragEndEvent
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import {
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

interface SmartListsProps {
  listId: string;
  listType: 'shopping' | 'todo' | 'punch-list';
  onBack: () => void;
}

export function VoiceEnabledSmartLists({ listId, listType, onBack }: SmartListsProps) {
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [newItem, setNewItem] = useState("");
  const [isAddingVoice, setIsAddingVoice] = useState(false);
  const [voiceTranscript, setVoiceTranscript] = useState("");

  // Voice input for adding items
  const { isRecording, isTranscribing, toggleRecording } = useVoice({
    onTranscriptionComplete: (text) => {
      if (text.trim()) {
        console.log('🎤 Voice input for list item:', text);
        setNewItem(text.trim());
        setVoiceTranscript("");
        setIsAddingVoice(false);
        // Auto-add the item
        addItemMutation.mutate({ 
          text: text.trim(), 
          listId, 
          priority: 'medium',
          category: listType === 'shopping' ? 'grocery' : 'task'
        });
      }
    },
    onTranscriptUpdate: (text) => {
      setVoiceTranscript(text);
    },
    onError: (error) => {
      console.error("🎤 Shopping list voice error:", error);
      setIsAddingVoice(false);
      setVoiceTranscript("");
      toast({
        title: "Voice Input Error",
        description: "Could not process voice input. Please try typing instead.",
        variant: "destructive"
      });
    }
  });

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // Get list items
  const { data: items = [], isLoading } = useQuery({
    queryKey: ["/api/lists", listId, "items"],
    enabled: !!listId,
    queryFn: () => api.getListItems(listId),
  });

  // Add item mutation
  const addItemMutation = useMutation({
    mutationFn: (data: { text: string; listId: string; priority: string; category: string }) => 
      api.addListItem(data.listId, {
        text: data.text,
        priority: data.priority,
        category: data.category,
        completed: false,
        quantity: 1
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/lists", listId, "items"] });
      setNewItem("");
      toast({
        title: "Item Added",
        description: "Item has been added to your list.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to add item.",
        variant: "destructive",
      });
    },
  });

  // Toggle completion mutation
  const toggleCompletionMutation = useMutation({
    mutationFn: (itemId: string) => api.toggleListItemCompletion(itemId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/lists", listId, "items"] });
    }
  });

  // Delete item mutation
  const deleteItemMutation = useMutation({
    mutationFn: (itemId: string) => api.deleteListItem(itemId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/lists", listId, "items"] });
      toast({
        title: "Item Deleted",
        description: "Item has been removed from your list.",
      });
    }
  });

  // Reorder items mutation
  const reorderItemsMutation = useMutation({
    mutationFn: (newOrder: string[]) => api.reorderListItems(listId, newOrder),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/lists", listId, "items"] });
    }
  });

  const handleAddItem = () => {
    if (newItem.trim()) {
      addItemMutation.mutate({ 
        text: newItem.trim(), 
        listId, 
        priority: 'medium',
        category: listType === 'shopping' ? 'grocery' : 'task'
      });
    }
  };

  const handleVoiceToggle = async () => {
    if (!isAddingVoice) {
      setIsAddingVoice(true);
      console.log('🎤 Starting voice input for shopping list');
    }
    try {
      await toggleRecording();
    } catch (error) {
      console.error('🎤 Voice toggle error:', error);
      setIsAddingVoice(false);
    }
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (over && active.id !== over.id) {
      const oldIndex = items.findIndex((item) => item.id === active.id);
      const newIndex = items.findIndex((item) => item.id === over.id);

      const newOrder = arrayMove(items, oldIndex, newIndex).map(item => item.id);
      reorderItemsMutation.mutate(newOrder);
    }
  };

  if (isLoading) {
    return <div className="text-center py-8">Loading list items...</div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <Button variant="ghost" onClick={onBack}>
          ← Back to Lists
        </Button>
        <h2 className="text-xl font-bold capitalize">{listType.replace('-', ' ')} List</h2>
      </div>

      {/* Voice-enabled Add Item Section */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center space-x-2">
            <Plus className="h-5 w-5" />
            <span>Add New Item</span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {/* Voice Input Controls */}
            {isAddingVoice && (
              <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-800">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-medium text-blue-800 dark:text-blue-200">
                    🎤 Voice Input Active
                  </span>
                  <Button 
                    variant="ghost" 
                    size="sm" 
                    onClick={() => {
                      setIsAddingVoice(false);
                      setVoiceTranscript("");
                    }}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
                {voiceTranscript && (
                  <div className="text-sm text-blue-700 dark:text-blue-300 mb-2">
                    Hearing: "{voiceTranscript}"
                  </div>
                )}
                <div className="text-xs text-blue-600 dark:text-blue-400">
                  {isRecording ? "🔴 Recording... speak now" : 
                   isTranscribing ? "🔄 Processing..." : 
                   "Click the microphone to start recording"}
                </div>
              </div>
            )}

            <div className="flex items-center space-x-2">
              <div className="flex-1">
                <Input
                  value={newItem}
                  onChange={(e) => setNewItem(e.target.value)}
                  placeholder={`Add ${listType === 'shopping' ? 'item to buy' : listType === 'todo' ? 'task to do' : 'item to fix'}...`}
                  onKeyPress={(e) => e.key === 'Enter' && handleAddItem()}
                  disabled={isAddingVoice}
                  data-testid="add-item-input"
                />
              </div>

              {/* Voice Input Button */}
              <Button
                onClick={handleVoiceToggle}
                disabled={isTranscribing}
                className={`
                  h-10 w-10 rounded-full transition-all duration-200
                  ${isRecording || isAddingVoice
                    ? "animate-pulse bg-red-500 hover:bg-red-600 text-white" 
                    : "bg-blue-500 hover:bg-blue-600 text-white"
                  }
                `}
                data-testid="voice-add-button"
              >
                <Mic className={`h-4 w-4 ${isRecording ? 'animate-pulse' : ''}`} />
              </Button>

              {/* Add Button */}
              <Button
                onClick={handleAddItem}
                disabled={!newItem.trim() || addItemMutation.isPending || isAddingVoice}
                className="h-10 w-10 rounded-full bg-green-500 hover:bg-green-600 text-white"
                data-testid="add-item-button"
              >
                {addItemMutation.isPending ? (
                  <div className="animate-spin h-4 w-4 border-2 border-white border-t-transparent rounded-full" />
                ) : (
                  <Plus className="h-4 w-4" />
                )}
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Items List with Drag & Drop */}
      <Card>
        <CardHeader>
          <CardTitle>Items ({items.length})</CardTitle>
        </CardHeader>
        <CardContent>
          {items.length === 0 ? (
            <div className="text-center py-8 text-gray-500">
              <Plus className="h-12 w-12 mx-auto mb-4 opacity-50" />
              <p>No items yet. Add some {listType === 'shopping' ? 'items to buy' : 'tasks'} to get started!</p>
            </div>
          ) : (
            <DndContext
              sensors={sensors}
              collisionDetection={closestCenter}
              onDragEnd={handleDragEnd}
            >
              <SortableContext
                items={items.map(item => item.id)}
                strategy={verticalListSortingStrategy}
              >
                <div className="space-y-2">
                  {items.map((item) => (
                    <SortableListItem
                      key={item.id}
                      item={item}
                      onToggleCompletion={() => toggleCompletionMutation.mutate(item.id)}
                      onDelete={() => deleteItemMutation.mutate(item.id)}
                    />
                  ))}
                </div>
              </SortableContext>
            </DndContext>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

// Sortable list item component
function SortableListItem({ item, onToggleCompletion, onDelete }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
  } = useSortable({ id: item.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={`
        flex items-center space-x-3 p-3 rounded-lg border
        ${item.completed 
          ? 'bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700' 
          : 'bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-700'
        }
      `}
      data-testid={`list-item-${item.id}`}
    >
      {/* Drag Handle */}
      <div {...attributes} {...listeners} className="cursor-grab active:cursor-grabbing">
        <GripVertical className="h-4 w-4 text-gray-400" />
      </div>

      {/* Completion Checkbox */}
      <Button
        variant="ghost"
        size="sm"
        onClick={onToggleCompletion}
        className={`
          h-6 w-6 rounded-full p-0
          ${item.completed 
            ? 'bg-green-500 text-white hover:bg-green-600' 
            : 'border-2 border-gray-300 hover:border-green-500'
          }
        `}
        data-testid={`toggle-completion-${item.id}`}
      >
        {item.completed && <Check className="h-3 w-3" />}
      </Button>

      {/* Item Text */}
      <div className="flex-1">
        <span className={`${item.completed ? 'line-through text-gray-500' : ''}`}>
          {item.text}
        </span>
        <div className="flex items-center space-x-2 mt-1">
          {item.category && (
            <Badge variant="secondary" className="text-xs">
              {item.category}
            </Badge>
          )}
          {item.priority && item.priority !== 'medium' && (
            <Badge 
              variant={item.priority === 'high' ? 'destructive' : 'outline'}
              className="text-xs"
            >
              {item.priority}
            </Badge>
          )}
          {item.quantity && item.quantity > 1 && (
            <Badge variant="outline" className="text-xs">
              {item.quantity}x
            </Badge>
          )}
        </div>
      </div>

      {/* Delete Button */}
      <Button
