import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Mic, Volume2, Play, Square, Upload } from 'lucide-react';

interface AlarmSoundPickerProps {
  onSoundChange?: (soundConfig: any) => void;
  onSoundSelected?: (soundConfig: any) => void;
  value?: any;
  currentSound?: any;
}

export function AlarmSoundPicker({ onSoundSelected, onSoundChange, value, currentSound }: AlarmSoundPickerProps) {
  const { getUserRingtones, generateVoiceAlarm, recordVoiceNote } = useAlarmSounds();

  const [soundType, setSoundType] = useState<'system' | 'ringtone' | 'voice-note' | 'ai-voice'>('system');
  const [ringtones, setRingtones] = useState<string[]>([]);
  const [selectedRingtone, setSelectedRingtone] = useState('default');
  const [voiceText, setVoiceText] = useState('Time to wake up! You have important things to do today.');
  const [voicePersonality, setVoicePersonality] = useState<'drill-sergeant' | 'gentle' | 'motivational' | 'funny' | 'angry-mom' | 'grandma'>('gentle');
  const [isRecording, setIsRecording] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [previewAudio, setPreviewAudio] = useState<HTMLAudioElement | null>(null);
  const [voiceNoteUrl, setVoiceNoteUrl] = useState<string | null>(null);

  useEffect(() => {
    loadRingtones();
  }, []);

  const loadRingtones = async () => {
    const availableRingtones = await getUserRingtones();
    setRingtones(availableRingtones);
  };

  const handleRecordVoiceNote = async () => {
    setIsRecording(true);
    try {
      const audioUrl = await recordVoiceNote();
      if (audioUrl) {
        setVoiceNoteUrl(audioUrl);
        const config = {
          type: 'voice-note',
          source: audioUrl
        };
        onSoundSelected?.(config);
        onSoundChange?.(config);
      }
    } catch (error) {
      console.error('Recording failed:', error);
    } finally {
      setIsRecording(false);
    }
  };

  const handleGenerateAIVoice = async () => {
    setIsGenerating(true);
    try {
      const audioUrl = await generateVoiceAlarm({
        text: voiceText,
        personality: voicePersonality
      });

      if (audioUrl) {
        const config = {
          type: 'ai-voice',
          source: audioUrl,
          voiceOptions: {
            text: voiceText,
            personality: voicePersonality
          }
        };
        onSoundSelected?.(config);
        onSoundChange?.(config);
      }
    } catch (error) {
      console.error('AI voice generation failed:', error);
    } finally {
      setIsGenerating(false);
    }
  };

  const setSelectedSound = (soundConfig: any) => {
    onSoundSelected?.(soundConfig);
    onSoundChange?.(soundConfig);
  };

  const playPreview = async (soundConfig: any) => {
    try {
      if (previewAudio) {
        previewAudio.pause();
        previewAudio.currentTime = 0;
      }

      let audioUrl = soundConfig.source;

      if (soundConfig.type === 'ai-voice' && !audioUrl) {
        setIsGenerating(true);
        audioUrl = await generateVoiceAlarm({
          text: voiceText,
          personality: voicePersonality
        });
        setIsGenerating(false);
      }

      if (audioUrl) {
        const audio = new Audio(audioUrl);
        audio.volume = 0.5;
        setPreviewAudio(audio);

        audio.addEventListener('ended', () => {
          setPreviewAudio(null);
        });

        await audio.play();
      }
    } catch (error) {
      console.error('Preview playback failed:', error);
    }
  };

  const stopPreview = () => {
    if (previewAudio) {
      previewAudio.pause();
      previewAudio.currentTime = 0;
      setPreviewAudio(null);
    }
  };

  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Volume2 className="h-5 w-5" />
          Alarm Sound
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Sound Type Selection */}
        <div className="space-y-2">
          <Label>Sound Type</Label>
          <Select value={soundType} onValueChange={(value: any) => setSoundType(value)}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="system">🔊 System Sounds</SelectItem>
              <SelectItem value="ringtone">📱 Device Ringtones</SelectItem>
              <SelectItem value="voice-note">🎤 Record Voice Note</SelectItem>
              <SelectItem value="ai-voice">🤖 AI Generated Voice</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Ringtone Selection */}
        {soundType === 'ringtone' && (
          <div className="space-y-2">
            <Label>Choose Ringtone</Label>
            <Select value={selectedRingtone} onValueChange={setSelectedRingtone}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {ringtones.map((ringtone) => (
                  <SelectItem key={ringtone} value={ringtone}>
                    {ringtone.replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase())}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setSelectedSound({ type: 'ringtone', source: selectedRingtone })}
              className="w-full"
            >
              Use This Ringtone
            </Button>
          </div>
        )}

        {/* Voice Note Recording */}
        {soundType === 'voice-note' && (
          <div className="space-y-3">
            <Label>Record Voice Note (Max 10 seconds)</Label>
            <div className="flex gap-2">
              <Button
                variant={isRecording ? "destructive" : "outline"}
                onClick={handleRecordVoiceNote}
                disabled={isRecording}
                className="flex-1"
              >
                <Mic className="h-4 w-4 mr-2" />
                {isRecording ? 'Recording...' : 'Record Voice Note'}
              </Button>

              {voiceNoteUrl && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => playPreview({ type: 'voice-note', source: voiceNoteUrl })}
                >
                  <Play className="h-4 w-4" />
                </Button>
              )}
            </div>

            {voiceNoteUrl && (
              <div className="p-2 bg-muted rounded text-sm">
                ✅ Voice note recorded successfully
              </div>
            )}
          </div>
        )}

        {/* AI Voice Configuration */}
        {soundType === 'ai-voice' && (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label>Wake-up Message</Label>
              <Textarea
                value={voiceText}
                onChange={(e) => setVoiceText(e.target.value)}
                placeholder="Enter your custom wake-up message..."
                rows={3}
                maxLength={200}
              />
              <div className="text-xs text-muted-foreground">
                {voiceText.length}/200 characters
              </div>
            </div>

            <div className="space-y-2">
              <Label>Voice Personality</Label>
              <Select value={voicePersonality} onValueChange={(value: any) => setVoicePersonality(value)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="gentle">😌 Gentle & Calm</SelectItem>
                  <SelectItem value="motivational">💪 Motivational Coach</SelectItem>
                  <SelectItem value="drill-sergeant">🎖️ Drill Sergeant</SelectItem>
                  <SelectItem value="funny">😄 Funny & Quirky</SelectItem>
                  <SelectItem value="angry-mom">😤 Angry Mom</SelectItem>
                  <SelectItem value="grandma">👵 Sweet Grandma</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="flex gap-2">
              <Button
                onClick={handleGenerateAIVoice}
                disabled={isGenerating || !voiceText.trim()}
                className="flex-1"
              >
                {isGenerating ? 'Generating...' : 'Generate AI Voice'}
              </Button>

              <Button
                variant="outline"
                size="sm"
                onClick={() => playPreview({
                  type: 'ai-voice',
                  voiceOptions: { text: voiceText, personality: voicePersonality }
                })}
                disabled={isGenerating}
              >
                <Play className="h-4 w-4" />
              </Button>
            </div>
          </div>
        )}

        {/* System Sound */}
        {soundType === 'system' && (
          <Button
            variant="outline"
            onClick={() => setSelectedSound({ type: 'system' })}
            className="w-full"
          >
            Use Default System Sound
          </Button>
        )}

        {/* Preview Controls */}
        {previewAudio && (
          <div className="flex items-center justify-between p-2 bg-muted rounded">
            <span className="text-sm">Playing preview...</span>
            <Button variant="ghost" size="sm" onClick={stopPreview}>
              <Square className="h-4 w-4" />
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import React, { useState } from 'react';
import { useCapacitorScheduler } from '@/hooks/use-capacitor-scheduler';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Calendar, Clock, Bell, Repeat } from 'lucide-react';
import { AlarmSoundPicker } from './alarm-sound-picker';

interface NativeSchedulerProps {
  onScheduled?: (alarmId: number) => void;
}

export function NativeScheduler({ onScheduled }: NativeSchedulerProps) {
  const { showDatePicker, scheduleAlarm } = useCapacitorScheduler();
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [recurring, setRecurring] = useState<'none' | 'daily' | 'weekly' | 'monthly' | 'yearly'>('none');
  const [vibration, setVibration] = useState(true);
  const [isScheduling, setIsScheduling] = useState(false);
  const [soundConfig, setSoundConfig] = useState<any>({ type: 'system' });

  const handleDatePicker = async (mode: 'date' | 'time' | 'datetime') => {
    const date = await showDatePicker({
      mode,
      theme: 'light' as const,
      min: new Date(), // Can't schedule in the past
    });

    if (date) {
      setSelectedDate(date);
    }
  };

  const handleSchedule = async () => {
    if (!title.trim() || !selectedDate) {
      return;
    }

    setIsScheduling(true);

    try {
      const alarmId = await scheduleAlarm({
        title: title.trim(),
        description: description.trim(),
        date: selectedDate,
        recurring,
        vibration,
        sound: soundConfig.source || 'default'
      });

      if (alarmId) {
        // Reset form
        setTitle('');
        setDescription('');
        setSelectedDate(null);
        setRecurring('none');

        // Notify parent component
        onScheduled?.(alarmId);

        // Show success feedback
        console.log(`✅ Alarm scheduled for ${selectedDate.toLocaleString()}`);
      } else {
        console.error('Failed to schedule alarm - scheduleAlarm returned null');
        alert('Failed to schedule alarm. Please check the date/time and try again.');
      }
    } catch (error) {
      console.error('Scheduling error:', error);
      // Show user-friendly error message
      alert(`Error scheduling alarm: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setIsScheduling(false);
    }
  };

  return (
    <Card className="w-full max-w-md">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Bell className="h-5 w-5" />
          Schedule Alarm
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Title Input */}
        <div className="space-y-2">
          <Label htmlFor="alarm-title">Title</Label>
          <Input
            id="alarm-title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Alarm title..."
            maxLength={50}
          />
        </div>

        {/* Description Input */}
        <div className="space-y-2">
          <Label htmlFor="alarm-description">Description (Optional)</Label>
          <Input
            id="alarm-description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Additional details..."
            maxLength={100}
          />
        </div>

        {/* Date/Time Pickers */}
        <div className="space-y-3">
          <Label>Schedule Time</Label>
          <div className="grid grid-cols-2 gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => handleDatePicker('date')}
              className="flex items-center gap-2"
            >
              <Calendar className="h-4 w-4" />
              Date
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => handleDatePicker('time')}
              className="flex items-center gap-2"
            >
              <Clock className="h-4 w-4" />
              Time
            </Button>
          </div>
          <Button
            variant="outline"
            onClick={() => handleDatePicker('datetime')}
            className="w-full flex items-center gap-2"
          >
            <Calendar className="h-4 w-4" />
            <Clock className="h-4 w-4" />
            Date & Time
          </Button>

          {selectedDate && (
            <div className="p-2 bg-muted rounded text-sm">
              Scheduled: {selectedDate.toLocaleString()}
            </div>
          )}
        </div>

        {/* Recurring Options */}
        <div className="space-y-2">
          <Label className="flex items-center gap-2">
            <Repeat className="h-4 w-4" />
            Repeat
          </Label>
          <Select value={recurring} onValueChange={(value: 'none' | 'daily' | 'weekly' | 'monthly' | 'yearly') => setRecurring(value)}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="none">No Repeat</SelectItem>
              <SelectItem value="daily">Daily</SelectItem>
              <SelectItem value="weekly">Weekly</SelectItem>
              <SelectItem value="monthly">Monthly</SelectItem>
              <SelectItem value="yearly">Yearly</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Alarm Sound Picker */}
        <AlarmSoundPicker 
          onSoundChange={setSoundConfig}
          value={soundConfig}
        />

        {/* Vibration Toggle */}
        <div className="flex items-center justify-between">
          <Label htmlFor="vibration">Vibration</Label>
          <Switch
            id="vibration"
            checked={vibration}
            onCheckedChange={setVibration}
          />
        </div>

        {/* Schedule Button */}
        <Button
          onClick={handleSchedule}
          disabled={!title.trim() || !selectedDate || isScheduling}
          className="w-full"
        >
          {isScheduling ? 'Scheduling...' : 'Schedule Alarm'}
        </Button>
      </CardContent>
    </Card>
  );
}

import React, { useState, useEffect } from 'react';
import { useCapacitorScheduler } from '@/hooks/use-capacitor-scheduler';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Trash2, Bell, Clock, Repeat } from 'lucide-react';

interface ScheduledAlarm {
  id: number;
  title: string;
  body?: string;
  schedule?: any;
}

export function ScheduledAlarms() {
  const { getScheduledAlarms, cancelAlarm } = useCapacitorScheduler();
  const [alarms, setAlarms] = useState<ScheduledAlarm[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const loadAlarms = async () => {
    setIsLoading(true);
    try {
      const scheduledAlarms = await getScheduledAlarms();
      console.log('📱 Loaded alarms:', scheduledAlarms);
      setAlarms(scheduledAlarms);
    } catch (error) {
      console.error('Failed to load alarms:', error);
      // Show some test alarms for debugging
      setAlarms([
        {
          id: 1,
          title: 'Morning Alarm',
          body: 'Wake up! Time to start your day!',
          schedule: { at: new Date(Date.now() + 3600000) } // 1 hour from now
        },
        {
          id: 2,
          title: 'Afternoon Reminder',
          body: 'Check your tasks',
          schedule: { at: new Date(Date.now() + 7200000) } // 2 hours from now
        }
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCancelAlarm = async (alarmId: number) => {
    const success = await cancelAlarm(alarmId);
    if (success) {
      setAlarms(prev => prev.filter(alarm => alarm.id !== alarmId));
    }
  };

  useEffect(() => {
    loadAlarms();
  }, []);

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-primary"></div>
            <span className="ml-2">Loading alarms...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (alarms.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Bell className="h-5 w-5" />
            Scheduled Alarms
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-center py-8 text-muted-foreground">
            <Bell className="h-12 w-12 mx-auto mb-4 opacity-50" />
            <p>No alarms scheduled</p>
            <p className="text-sm">Use the scheduler above to create your first alarm</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
        <CardTitle className="flex items-center gap-2">
          <Bell className="h-5 w-5" />
          Scheduled Alarms ({alarms.length})
        </CardTitle>
        <Button variant="outline" size="sm" onClick={loadAlarms}>
          Refresh
        </Button>
      </CardHeader>
      <CardContent>
        <div className="space-y-3">
          {alarms.map((alarm) => (
            <div
              key={alarm.id}
              className="flex items-center justify-between p-3 border rounded-lg"
            >
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <h4 className="font-medium truncate">{alarm.title}</h4>
                  {alarm.schedule?.repeats && (
                    <Badge variant="secondary" className="text-xs">
                      <Repeat className="h-3 w-3 mr-1" />
                      Recurring
                    </Badge>
                  )}
                </div>

                {alarm.body && (
                  <p className="text-sm text-muted-foreground truncate">
                    {alarm.body}
                  </p>
                )}

                {alarm.schedule?.at && (
                  <div className="flex items-center gap-1 mt-1 text-xs text-muted-foreground">
                    <Clock className="h-3 w-3" />
                    {new Date(alarm.schedule.at).toLocaleString()}
                  </div>
                )}
              </div>

              <Button
                variant="ghost"
                size="sm"
                onClick={() => handleCancelAlarm(alarm.id)}
                className="text-destructive hover:text-destructive"
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

// Voice command integration helper
export function VoiceSchedulerCommands() {
  const { scheduleAlarm, showDatePicker } = useCapacitorScheduler();

  const processVoiceCommand = async (command: string): Promise<boolean> => {
    const lowerCommand = command.toLowerCase();

    // Parse various voice patterns
    if (lowerCommand.includes('set alarm') || lowerCommand.includes('wake me up')) {
      // Extract time patterns like "set alarm for 7am", "wake me up at 8:30"
      const timeMatch = lowerCommand.match(/(?:at|for)\s+(\d{1,2}):?(\d{2})?\s*(am|pm)?/);

      if (timeMatch) {
        const hour = parseInt(timeMatch[1]);
        const minute = parseInt(timeMatch[2]) || 0;
        const isPM = timeMatch[3] === 'pm';

        const alarmTime = new Date();
        alarmTime.setHours(isPM && hour !== 12 ? hour + 12 : hour, minute, 0, 0);

        // If time is in the past, schedule for tomorrow
        if (alarmTime < new Date()) {
          alarmTime.setDate(alarmTime.getDate() + 1);
        }

        const alarmId = await scheduleAlarm({
          title: 'Voice Alarm',
          description: `Scheduled via voice: "${command}"`,
          date: alarmTime,
          recurring: 'none',
          vibration: true
        });

        return !!alarmId;
      }
    }

    // Timer commands like "set timer for 30 minutes"
    if (lowerCommand.includes('timer')) {
      const minuteMatch = lowerCommand.match(/(\d+)\s*minute/);
      const hourMatch = lowerCommand.match(/(\d+)\s*hour/);

      let totalMinutes = 0;
      if (minuteMatch) totalMinutes += parseInt(minuteMatch[1]);
      if (hourMatch) totalMinutes += parseInt(hourMatch[1]) * 60;

      if (totalMinutes > 0) {
        const timerDate = new Date();
        timerDate.setMinutes(timerDate.getMinutes() + totalMinutes);

        const alarmId = await scheduleAlarm({
          title: `${totalMinutes} Minute Timer`,
          description: `Voice timer: "${command}"`,
          date: timerDate,
          recurring: 'none',
          vibration: true
        });

        return !!alarmId;
      }
    }

    return false;
  };

  return { processVoiceCommand };
}

import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
